local g = {id="nightelf-rogue",name="Night Elf Rogue",class="ROGUE",race="NightElf",abilityWord="Ability",abilitiesWord="abilities",chapters={{name="Shadowglen",first=1,last=7,lo=1,hi=6},{name="Dolanaar",first=8,last=15,lo=6,hi=10},{name="Darnassus",first=16,last=20,lo=10,hi=12},{name="Darkshore",first=21,last=29,lo=12,hi=20},{name="Poisons quest",first=30,last=32,lo=20,hi=20},{name="Ashenvale & Wetlands",first=33,last=40,lo=20,hi=28},{name="Duskwood to Arathi",first=41,last=46,lo=28,hi=32},{name="Stranglethorn Vale",first=47,last=51,lo=33,hi=40},{name="Riverglades",first=52,last=58,lo=37,hi=45},{name="Tanaris & Feralas",first=59,last=68,lo=43,hi=50},{name="Un'Goro to 60",first=69,last=81,lo=49,hi=60}},spells={sinister={name="Sinister Strike",lv=1,icon="spell_shadow_ritualofsacrifice",text="Your main attack all the way to 60. Adds 1 combo point.",type="Ability"},eviscerate={name="Eviscerate",lv=1,icon="ability_rogue_eviscerate",text="Finisher. Uses all your combo points for one big hit. Best at 3 to 5 points.",type="Ability"},slicedice={name="Slice and Dice",lv=10,icon="ability_rogue_slicedice",text="Finisher. You attack faster for a while. Keep it running all fight.",type="Ability"},gouge={name="Gouge",lv=6,icon="ability_gouge",text="Stuns the enemy for a few seconds. Any hit wakes it up. Use it to get behind it, or to get away.",type="Ability"},kick={name="Kick",lv=12,icon="ability_kick",text="Stops an enemy's spell while they're casting it.",type="Ability"},throw={name="Throw",lv=1,icon="ability_throw",text="Throws your throwing weapon. Use it to pull one enemy from a group, or to hit a runner.",type="Ability"},sprint={name="Sprint",lv=10,icon="ability_rogue_sprint",text="Run much faster for a few seconds. Your escape button, together with Vanish.",type="Ability"},evasion={name="Evasion",lv=8,icon="spell_shadow_shadowward",text="You dodge most attacks for a while. Press it when two enemies attack you.",type="Ability"},vanish={name="Vanish",lv=22,icon="ability_vanish",text="You disappear into Stealth and enemies forget you. Uses a Flash Powder. Press it when a fight goes wrong.",type="Ability"},eluneslight={name="Elune's Light",lv=1,icon="spell_holy_elunesgrace",text="Night elf racial, new in WoW Forever. For a short time you get more critical strikes. Use it for hard fights.",type="Racial"},riposte={name="Riposte",lv=20,icon="ability_warrior_challange",text="Lights up after you parry. Press it for a free hit that disarms the enemy.",type="Talent"},stealth={name="Stealth",lv=1,icon="ability_stealth",text="Makes you almost invisible. You move slower. Any attack breaks it. Start most fights from it.",type="Ability"},cheapshot={name="Cheap Shot",lv=26,icon="ability_cheapshot",text="Opener from Stealth. Stuns the enemy for a few seconds and gives 2 combo points.",type="Ability"},backstab={name="Backstab",lv=4,icon="ability_backstab",text="Big hit from behind. Needs a dagger in your main hand. Great from Stealth, or after Gouge.",type="Ability"},garrote={name="Garrote",lv=14,icon="ability_rogue_garrote",text="Opener from Stealth, behind the enemy. Makes it bleed for a while.",type="Ability"},kidney={name="Kidney Shot",lv=30,icon="ability_rogue_kidneyshot",text="Finisher that stuns. More combo points, longer stun.",type="Ability"},bladeflurry={name="Blade Flurry",lv=30,icon="ability_warrior_punishingblow",text="For 15 seconds you attack faster and every hit also hits a second enemy. For fights against two.",type="Talent"},coldblood={name="Cold Blood",lv=60,icon="spell_ice_lament",text="Your next Sinister Strike, Backstab, Ambush or Eviscerate always crits. Press it right before a 5-point Eviscerate.",type="Talent"},adrenaline={name="Adrenaline Rush",lv=40,icon="spell_shadow_shadowworddominate",text="Energy fills twice as fast for a short time. Your big button for hard fights.",type="Talent"},shadowmeld={name="Shadowmeld",lv=1,icon="ability_ambush",text="Night elf racial. Hide in the shadows as long as you stand still. Works even in a fight to drop out of it.",type="Racial"},feint={name="Feint",lv=16,icon="ability_rogue_feint",text="Makes enemies less angry at you. Twice as strong in WoW Forever. For dungeons.",type="Ability"},exposearmor={name="Expose Armor",lv=14,icon="ability_warrior_riposte",text="Finisher. The enemy takes more physical damage. Only worth it on bosses.",type="Ability"},blind={name="Blind",lv=34,icon="spell_shadow_mindsteal",text="Takes one enemy out of the fight for a while. Uses a Blinding Powder.",type="Ability"},shank={name="Shank",lv=24,icon="ability_rogue_shadowstrikes",text="New rogue attack in WoW Forever. Use it between Sinister Strikes when it's ready.",type="Ability"},sap={name="Sap",lv=10,icon="ability_sap",text="From Stealth, puts a humanoid to sleep for a while. In WoW Forever it doesn't break your Stealth.",type="Ability"},ipois1={name="Instant Poison",lv=20,icon="ability_poisons",text="Main-hand poison. Extra Nature damage on some hits. Made with Poisons.",type="Ability"},ipois2={name="Instant Poison II",lv=28,icon="ability_poisons",text="Better Instant Poison for your main hand.",type="Ability"},ipois3={name="Instant Poison III",lv=36,icon="ability_poisons",text="Better Instant Poison for your main hand.",type="Ability"},ipois4={name="Instant Poison IV",lv=44,icon="ability_poisons",text="Better Instant Poison for your main hand.",type="Ability"},ipois5={name="Instant Poison V",lv=52,icon="ability_poisons",text="Better Instant Poison for your main hand.",type="Ability"},ipois6={name="Instant Poison VI",lv=60,icon="ability_poisons",text="Best Instant Poison for your main hand.",type="Ability"},opois1={name="Crippling Poison",lv=20,icon="ability_poisonsting",text="Off-hand poison until 30. Slows the enemy, so it can't run away.",type="Ability"},opois2={name="Deadly Poison",lv=30,icon="ability_rogue_dualweild",text="Off-hand poison from 30. Extra damage over time that stacks.",type="Ability"},opois3={name="Deadly Poison II",lv=38,icon="ability_rogue_dualweild",text="Better Deadly Poison for your off hand.",type="Ability"},opois4={name="Deadly Poison III",lv=46,icon="ability_rogue_dualweild",text="Better Deadly Poison for your off hand.",type="Ability"},opois5={name="Deadly Poison IV",lv=54,icon="ability_rogue_dualweild",text="Best Deadly Poison for your off hand.",type="Ability"},poisons={name="Poisons",lv=20,icon="trade_brewpoison",text="Opens the Poisons window, where you make your poisons. Learned from the level 20 rogue quest.",type="Ability"},stone1={name="Rough Sharpening Stone",lv=10,icon="inv_stone_sharpeningstone_01",text="Rub it on a sword, axe or dagger for extra damage. Works together with poisons in WoW Forever. Made by blacksmiths: auction house.",type="Item"},stone2={name="Coarse Sharpening Stone",lv=15,icon="inv_stone_sharpeningstone_02",text="Better sharpening stone.",type="Item"},stone3={name="Heavy Sharpening Stone",lv=25,icon="inv_stone_sharpeningstone_03",text="Better sharpening stone.",type="Item"},stone4={name="Solid Sharpening Stone",lv=35,icon="inv_stone_sharpeningstone_04",text="Better sharpening stone.",type="Item"},stone5={name="Dense Sharpening Stone",lv=45,icon="inv_stone_sharpeningstone_05",text="Best sharpening stone.",type="Item"},pickpocket={name="Pick Pocket",lv=4,icon="inv_misc_bag_11",text="From Stealth, steals money and small items from a humanoid. Do it before every humanoid fight.",type="Ability"},picklock={name="Pick Lock",lv=16,icon="spell_nature_moonkey",text="Opens locked boxes and some locked doors. Click it, then the box in your bags.",type="Ability"},detecttraps={name="Detect Traps",lv=24,icon="ability_spy",text="Shows traps near you.",type="Ability"},disarmtrap={name="Disarm Trap",lv=30,icon="spell_shadow_grimward",text="Removes a trap so nobody steps on it.",type="Ability"},firstaid={name="First Aid",lv=10,icon="spell_holy_sealofsacrifice",text="Opens First Aid, where you make bandages from cloth. Learn it in Darnassus.",type="Item"},hearth={name="Hearthstone",lv=1,icon="inv_misc_rune_01",text="Takes you to the inn you set as home. 1 hour cooldown.",type="Item"},mount={name="Striped Nightsaber",lv=40,icon="ability_mount_blackpanther",text="Your night elf mount. Buy it from Lelanai in Darnassus.",type="Item"},bandage1={name="Linen Bandage",lv=10,icon="inv_misc_bandage_15",text="Heals you over a few seconds. Made with First Aid from Linen Cloth. Needs First Aid 1.",type="Item"},bandage2={name="Heavy Linen Bandage",lv=14,icon="inv_misc_bandage_18",text="Better bandage. Needs First Aid 40.",type="Item"},bandage3={name="Wool Bandage",lv=20,icon="inv_misc_bandage_14",text="Better bandage, from Wool Cloth. Needs First Aid 80.",type="Item"},bandage4={name="Heavy Wool Bandage",lv=24,icon="inv_misc_bandage_17",text="Better bandage. Needs First Aid 115.",type="Item"},bandage5={name="Silk Bandage",lv=28,icon="inv_misc_bandage_01",text="Better bandage, from Silk Cloth. Needs First Aid 150.",type="Item"},bandage6={name="Heavy Silk Bandage",lv=32,icon="inv_misc_bandage_02",text="Better bandage. Needs First Aid 180.",type="Item"},bandage7={name="Mageweave Bandage",lv=36,icon="inv_misc_bandage_19",text="Better bandage, from Mageweave Cloth. Needs First Aid 210.",type="Item"},bandage8={name="Heavy Mageweave Bandage",lv=40,icon="inv_misc_bandage_20",text="Better bandage. Needs First Aid 240.",type="Item"},bandage9={name="Runecloth Bandage",lv=46,icon="inv_misc_bandage_11",text="Better bandage, from Runecloth. Needs First Aid 260.",type="Item"},bandage10={name="Heavy Runecloth Bandage",lv=52,icon="inv_misc_bandage_12",text="Best bandage. Needs First Aid 290.",type="Item"},food1={name="Shiny Red Apple",lv=1,icon="inv_misc_food_19",text="Eat it after a fight to refill health. Sold by food vendors.",type="Item"},food2={name="Tel'Abim Banana",lv=5,icon="inv_misc_food_24",text="Better food from a food vendor.",type="Item"},food3={name="Snapvine Watermelon",lv=15,icon="inv_misc_food_22",text="Better food from a food vendor.",type="Item"},food4={name="Goldenbark Apple",lv=25,icon="inv_misc_food_20",text="Better food from a food vendor.",type="Item"},food5={name="Moon Harvest Pumpkin",lv=35,icon="inv_misc_food_29",text="Better food from a food vendor.",type="Item"},food6={name="Deep Fried Plantains",lv=45,icon="inv_misc_food_55",text="Better food from a food vendor.",type="Item"},food7={name="Homemade Cherry Pie",lv=55,icon="inv_misc_food_10",text="Best vendor food. Sold by bakers.",type="Item"}},bars={{id="main",title="Main bar",how="Keys 1 to =. Everything you press in a normal fight.",slots={{key="1",uses={{1,"sinister"}}},{key="2",uses={{1,"eviscerate"}}},{key="3",uses={{10,"slicedice"}}},{key="4",uses={{6,"gouge"}}},{key="5",uses={{12,"kick"}}},{key="6",uses={{1,"throw"}}},{key="7",uses={{10,"sprint"}}},{key="8",uses={{8,"evasion"}}},{key="9",uses={{22,"vanish"}}},{key="0",uses={{1,"eluneslight"}}},{key="-",uses={{20,"riposte"}}},{key="=",uses={{1,"stealth"}}}}},{id="shift",title="Bottom left bar",how="Shift + 1 to =. Openers, stuns, emergencies and rarer abilities.",slots={{key="S1",uses={{26,"cheapshot"}}},{key="S2",uses={{4,"backstab"}}},{key="S3",uses={{14,"garrote"}}},{key="S4",uses={{30,"kidney"}}},{key="S5",uses={{30,"bladeflurry"}}},{key="S6",uses={{40,"adrenaline"}}},{key="S7",uses={{1,"shadowmeld"}}},{key="S8",uses={{16,"feint"}}},{key="S9",uses={{14,"exposearmor"}}},{key="S0",uses={{34,"blind"}}},{key="S-",uses={{24,"shank"}}},{key="S=",uses={{10,"sap"}}}}},{id="side",title="Right bar",how="Click these with the mouse between fights. No key needed.",slots={{uses={{20,"ipois1"},{28,"ipois2"},{36,"ipois3"},{44,"ipois4"},{52,"ipois5"},{60,"ipois6"}}},{uses={{20,"opois1"},{30,"opois2"},{38,"opois3"},{46,"opois4"},{54,"opois5"}}},{uses={{20,"poisons"}}},{uses={{10,"stone1"},{15,"stone2"},{25,"stone3"},{35,"stone4"},{45,"stone5"}}},{uses={{4,"pickpocket"}}},{uses={{16,"picklock"}}},{uses={{24,"detecttraps"}}},{uses={{30,"disarmtrap"}}},{uses={{10,"firstaid"}}},{uses={{1,"hearth"}}},{uses={{40,"mount"}}},{uses={{60,"coldblood"}}}}},{id="alt",title="Bottom right bar",how="Alt + 1 and Alt + 2. Bandages and food. Use them after fights.",slots={{key="A1",uses={{10,"bandage1"},{14,"bandage2"},{20,"bandage3"},{24,"bandage4"},{28,"bandage5"},{32,"bandage6"},{36,"bandage7"},{40,"bandage8"},{46,"bandage9"},{52,"bandage10"}}},{key="A2",uses={{1,"food1"},{5,"food2"},{15,"food3"},{25,"food4"},{35,"food5"},{45,"food6"},{55,"food7"}}}}}},talents={{lv="10–11",lo=10,hi=11,name="Efficient Strikes (Combat tab)",how="Click it 2 times (once per level)",why="Sinister Strike costs less energy."},{lv="12–14",lo=12,hi=14,name="Coup de Grace",how="3 times",why="Eviscerate hits harder."},{lv="15–16",lo=15,hi=16,name="Precision",how="2 times",why="You miss less often."},{lv="17–19",lo=17,hi=19,name="Deflection",how="3 times",why="You parry more attacks. Riposte needs all 3."},{lv="20",lo=20,hi=20,name="Riposte",how="Once",why="A free counter-attack after you parry. Press it when it lights up."},{lv="21",lo=21,hi=21,name="Precision",how="Once more (3 of 3)"},{lv="22–23",lo=22,hi=23,name="Composure",how="2 times",why="Poised saves you even more energy at the start of a fight."},{lv="24",lo=24,hi=24,name="Endurance",how="Once",why="Sprint and Evasion come back sooner."},{lv="25",lo=25,hi=25,name="Flawless Execution",how="Once",why="Eviscerate costs 15 less energy."},{lv="26–27",lo=26,hi=27,name="Weapon Expertise",how="2 times",why="Enemies dodge and parry you less often."},{lv="28–29",lo=28,hi=29,name="Aggression",how="2 times",why="Sinister Strike and Eviscerate hit harder."},{lv="30",lo=30,hi=30,name="Blade Flurry",how="Once",why="For 15 seconds you attack faster and every hit also hits a second enemy."},{lv="31–34",lo=31,hi=34,name="Hack and Slash",how="4 times",why="A bonus for whatever weapon you hold: swords, axes, maces, fists or daggers."},{lv="35–39",lo=35,hi=39,name="Flash of Steel",how="5 times",why="Shank gives you more energy and is ready sooner."},{lv="40",lo=40,hi=40,name="Adrenaline Rush",how="Once",why="Energy fills twice as fast for 15 seconds. Your big button."},{lv="41",lo=41,hi=41,name="Hack and Slash",how="Once more (5 of 5)"},{lv="42",lo=42,hi=42,name="Aggression",how="Once more (3 of 3)"},{lv="43–44",lo=43,hi=44,name="Dual Wield Specialization",how="2 times",why="Your off-hand weapon hits harder."},{lv="45–46",lo=45,hi=46,name="Remorseless Attacks (Assassination tab)",how="2 times",why="Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit."},{lv="47–49",lo=47,hi=49,name="Malice",how="3 times",why="More critical hits."},{lv="50–52",lo=50,hi=52,name="Ruthlessness",how="3 times",why="Finishers sometimes give a free combo point."},{lv="53–54",lo=53,hi=54,name="Malice",how="2 more times (5 of 5)"},{lv="55",lo=55,hi=55,name="Blood Splatter",how="Once",why="Rupture and Garrote last longer."},{lv="56–57",lo=56,hi=57,name="Improved Slice and Dice",how="2 times",why="Slice and Dice lasts longer."},{lv="58–59",lo=58,hi=59,name="Lethality",how="2 times",why="Your critical hits do more damage."},{lv="60",lo=60,hi=60,name="Cold Blood",how="Once",why="A button: your next attack always crits. Use it before Eviscerate. That's all 51 points."}},words={{label="Action bar",text="The row of buttons at the bottom of your screen. Each button has a key: 1 uses the first button, 2 the second, and so on."},{label="Auction house",text="Where players buy and sell items. Every big city has one."},{label="Buff",text="A good effect on you, like Slice and Dice. Its icon shows at the top right of your screen."},{label="Combo points",text="Small dots on the enemy's portrait. Sinister Strike and other attacks add them, up to 5. Finishers like Eviscerate use them all: more points, bigger effect."},{label="Cooldown",text="Waiting time before you can use an ability again. The button shows a clock-style sweep."},{label="Critical",text="A critical hit (\"crit\") does about double damage. Its number pops up bigger."},{label="Dungeon",text="A private area for a group of 5 players, with bosses and better loot."},{label="Elite",text="A much stronger enemy. Its portrait has a golden dragon border. Skip these alone."},{label="Elites",text="Much stronger enemies with a golden dragon border on their portrait. Skip them alone.",hide=true},{label="Energy",text="The yellow bar under your health. Rogue attacks cost energy instead of mana. It fills up by itself in a few seconds."},{label="Escort",text="A quest where you walk with an NPC and keep them alive until they're safe. Stay close and don't run ahead."},{label="Finisher",text="An attack that uses up your combo points, like Eviscerate, Slice and Dice or Kidney Shot."},{label="Flight path",text="Talk to a flight master (the person with a hippogryph or gryphon) once to unlock that place. Then you can fly between any places you've unlocked."},{label="Graveyard",text="Where you appear as a ghost when you die. Run back to your body and click Resurrect."},{label="Hearthstone",text="A stone in your bag that teleports you to the inn you set as home. Usable once an hour."},{label="Humanoid",text="Enemies shaped like people: humans, trolls, furbolgs, gnolls and so on. They often drop cloth and coins."},{label="Inn",text="Every town's inn has an innkeeper. Make it your home for your Hearthstone, and log out there for bonus XP."},{label="Legacy",text="A Forever system: you earn points across your whole account and spend them on bonuses. Press Y."},{label="NPC",text="A character run by the game, not by a player: quest givers, trainers, vendors, guards."},{label="Opener",text="An attack you can only use from Stealth, like Cheap Shot or Garrote. It starts the fight on your terms."},{label="Poison",text="Rogue-only. You make poisons and put them on your weapons, so your hits do extra damage."},{label="Pull",text="Starting a fight with an enemy, for example by hitting it or throwing a knife at it."},{label="PvP",text="Fighting other players. On PvP servers, the other faction can attack you in some zones."},{label="Quest log",text="Your list of quests. Press L. Click a quest to read what to do and where."},{label="Racial",text="An ability you get from your race, not your class."},{label="Rank",text="A stronger version of an ability you already have. Learn it at your trainer; it replaces the old one in your spellbook."},{label="Respawn",text="Enemies come back a few minutes after you kill them, so don't rest too long in a camp you cleared."},{label="Rested XP",text="Bonus XP you build up while logged out in an inn or city. Your XP bar turns blue while you have it."},{label="Spellbook",text="Every ability you've learned. Press P, then drag an ability from it onto your action bar."},{label="Stealth",text="Makes you almost invisible. Enemies only notice you when you get very close. Attacking breaks it."},{label="Stun",text="The enemy can't move or attack for a few seconds. Gouge, Cheap Shot and Kidney Shot stun."},{label="Talent",text="One point per level from 10. You spend it in the talent window (N) to make yourself stronger."},{label="Tank",text="The group member (often a warrior) whose job is to make enemies attack them, not you."},{label="Trainer",text="An NPC who teaches you new abilities for gold. Rogues need one every 2 levels."},{label="Vendor",text="An NPC who sells things and buys your junk. While talking to one, right-click an item in your bags to sell it."},{label="XP",text="Experience points. Quests and kills give XP. Fill the bar at the bottom of your screen to reach the next level."},{label="Zone",text="A big area of the world with its own name, like Darkshore or Dun Morogh. Its name shows above your minimap."}},pages={barsIntro="Where every ability should go, level by level. The main bar has what you press in every fight, on keys you reach without looking. Openers, stuns and emergency abilities go on |cff7fd4ffShift|r + number. Things you only use between fights go on the right bar, to click with the mouse. Hover over or tap a button to see what it does.",barsSetup="|cffffd200How to set this up in game|r\n\n1.  Press |cff7fd4ffEsc|r > |cffffd200Interface|r > |cffffd200Action Bars|r. Turn on the |cffffd200Bottom Left Bar|r, the |cffffd200Bottom Right Bar|r and the |cffffd200Right Bar|r.\n2.  Press |cff7fd4ffEsc|r > |cffffd200Key Bindings|r. Find |cffffd200Bottom Left Action Button 1|r to |cffffd20012|r and set them to |cff7fd4ffShift|r + |cff7fd4ff1|r … |cff7fd4ffShift|r + |cff7fd4ff=|r. Then set |cffffd200Bottom Right Action Button 1|r and |cffffd2002|r to |cff7fd4ffAlt|r + |cff7fd4ff1|r and |cff7fd4ffAlt|r + |cff7fd4ff2|r.\n3.  Open your spellbook (|cff7fd4ffP|r) and drag each ability to its place. Poisons, sharpening stones, bandages and food are items: drag them from your bags (|cff7fd4ffB|r) instead.\n4.  Turn on |cffffd200Lock Action Bars|r in the same Action Bars menu so you can't drag spells off by accident.",play="|cffffd200Quests|r\n\n•  A yellow |cffffff00!|r over someone's head means they have a quest for you. Click them and press Accept.\n•  A yellow |cffffff00?|r means you can hand in a finished quest there.\n•  Press |cff7fd4ffL|r to see your quests. Each one says what to do and where.\n•  Most of your XP comes from quests, so do every one you find.\n\n|cffffd200Fighting|r\n\n•  Click an enemy to target it, walk right up to it, and press your attack key. Rogues fight up close.\n•  Fight one enemy at a time. Rogues hit hard but only wear leather. Sneak past the enemies you don't need with Stealth.\n•  Enemy level colours: |cff9d9d9dgrey|r gives no XP, |cff1eff00green|r is easy, |cffffff00yellow|r is a fair fight, |cffff8000orange|r is hard and |cffff2020red|r means run.\n•  A golden dragon border on the portrait means |cffffd200elite|r. Don't fight those alone.\n\n|cffffd200After every fight|r\n\n•  Health low? Eat (|cff7fd4ffAlt|r + |cff7fd4ff2|r). You sit down by yourself while eating. Don't move until the bar is full.\n•  From level 10, use a bandage first (|cff7fd4ffAlt|r + |cff7fd4ff1|r), then eat. You make bandages yourself with First Aid from the cloth enemies drop. Buy food from food vendors.\n•  Rogues use energy, not mana, so you never need to drink.\n\n|cffffd200Getting stronger|r\n\n•  |cffffd200Every 2 levels|r, visit a rogue trainer and learn everything you can afford.\n•  |cffffd200Every level from 10|r, press |cff7fd4ffN|r and spend a talent point. See the |cffffd200Talents|r tab.\n•  New abilities go into your spellbook (|cff7fd4ffP|r). The |cffffd200Action Bars|r tab shows where to put them.\n\n|cffffd200Gear: is this item better?|r\n\nThe colour of an item's name tells you how good it is:\n|cff9d9d9dGrey|r Poor: sell it\n|cffffffffWhite|r Common: basic\n|cff1eff00Green|r Uncommon: a good upgrade\n|cff0070ddBlue|r Rare: great, often from dungeons\n|cffa335eePurple|r Epic: the best, from raids\n|cff9a9a9aYou're wearing:|r |cffffd200Leather Vest|r, Chest · Leather, 60 Armor\n|cff9a9a9avs|r\n|cff9a9a9aYou just found:|r |cffffd200Vest of the Monkey|r, Chest · Leather, 64 Armor, |cff1eff00+5 Agility|r, |cff1eff00+4 Stamina|r\n\nBetter: it has |cffffd200Agility|r, the stat rogues want most. Put it on.\n•  |cffffd200What you can wear:|r |cffffd200leather|r armor (cloth too, but leather is better). Rogues can't wear mail or plate.\n•  |cffffd200Stats to look for:|r |cffffd200Agility|r first (more damage, more critical hits, more dodging), then |cffffd200Stamina|r (more health) and |cffffd200Strength|r. Skip Intellect and Spirit: they're for spellcasters.\n•  |cffffd200Name endings:|r green items often end in a word that tells you their stats. |cffffd200of the Monkey|r (Agility + Stamina) and |cffffd200of the Tiger|r (Strength + Agility) are great for you. |cffffd200of the Owl|r and |cffffd200of the Eagle|r are for casters.\n•  |cffffd200Weapons:|r one in each hand. Look at the |cffffd200damage per second|r number: higher is better. A slow weapon (speed 2.4 or more) goes in your main hand, a fast one in your off hand. Your talents like swords; daggers are fine early on.\n•  |cffffd200How to compare:|r point at the new item and hold |cff7fd4ffShift|r. The game shows what you're wearing right next to it. Right-click an item in your bags to put it on.\n•  |cffffd200Easy mode:|r the |cffffd200Pawn|r addon (see |cffffd200Addons|r (on the website)) puts a green arrow on items that are an upgrade for you.\n•  |cffffd200Quest rewards:|r when you can pick one, take the one with Agility. If none fits, take the one that sells for the most.\n\n|cffffd200Getting around|r\n\n•  Talk to the innkeeper in each new town and choose \"Make this inn your home\". Your Hearthstone then brings you back there.\n•  Talk to every flight master (the person with a hippogryph or gryphon) you pass, so you can fly there later.\n•  If you die, you appear as a ghost at a graveyard. Run back to your body and click \"Resurrect\". As a night elf you're a fast wisp while dead (Wisp Spirit).\n•  Log out inside an inn to get bonus XP next time.\n\n|cffffd200Addons|r\n\nAddons are free extras that improve the game's interface. You don't need any, but a few make leveling much easier. The |cffffd200Addons page|r (on the website) lists which ones to get (must-have, recommended, optional, and a separate list for dungeons) and how to install them.\n\n|cffffd200Waypoint arrow:|r with the |cffffd200TomTom|r addon, click a pin on any Quest Guide map and press |cffffd200Copy /way|r. In game, press |cff7fd4ffEnter|r, paste with |cff7fd4ffCtrl|r + |cff7fd4ffV|r and press |cff7fd4ffEnter|r again. An arrow points the way. |cffffd200/way reset all|r clears it.\n\n|cffffd200Useful keys|r\n\n|cff7fd4ffL|r  Quest log      |cff7fd4ffM|r  Map\n|cff7fd4ffP|r  Spellbook      |cff7fd4ffN|r  Talents\n|cff7fd4ffC|r  Your character      |cff7fd4ffB|r  Bags\n|cff7fd4ffX|r  Sit down      |cff7fd4ffY|r  Legacy (from about level 25)\n\n|cffffd200The one combo to learn|r\n\n1.  |cffffd200Stealth|r and walk up to the enemy. Steal from humanoids with Pick Pocket first.\n2.  Open with |cffffd200Cheap Shot|r (from level 26) or Sinister Strike.\n3.  |cffffd200Slice and Dice|r as soon as you have 1 or 2 combo points.\n4.  |cffffd200Sinister Strike|r until you have 5 combo points.\n5.  |cffffd200Eviscerate|r. Keep Slice and Dice running, and Gouge or Kick the enemy when it starts casting a spell.",talentsIntro="From level 10 you get one talent point each level. Press |cff7fd4ffN|r, pick the |cffffd200Combat|r tab, and click the talent from this list. If one is greyed out, take the next one and come back.",talentsHint="Made a mistake? Any rogue trainer in a big city can reset your talents for a little gold. From level 40 you can also learn a second talent setup (Dual Specialization)."}}
g.steps = {
  {kind="start",chapter=1,lv="1",lo=1,hi=1,place="Shadowglen",title="Before you do anything",todo={"Press |cff7fd4ffP|r to open your |cffe2c6ff|Hwfw:29|hspellbook|h|r.","Drag each ability from your |cffe2c6ff|Hwfw:29|hspellbook|h|r to the key shown in the |cffffd200|cffe2c6ff|Hwfw:1|hAction bar|h|r|r box below. If the extra bars aren't showing yet, see |cffffd200How to set this up in game|r on the Action Bars tab.","Rogues don't use mana. Your yellow bar is |cffffd200|cffe2c6ff|Hwfw:10|henergy|h|r|r: every attack costs some, and it fills up again by itself in a few seconds."},done="every ability in the |cffffd200|cffe2c6ff|Hwfw:1|hAction bar|h|r|r box below is on its key.",tip="Sinister Strike is already on key |cff7fd4ff1|r and Eviscerate on |cff7fd4ff2|r. Strike three times, then Eviscerate. That's your whole fight for now.",bars={head="Action bar",rows={{id="sinister",where="Key |cff7fd4ff1|r |cff9a9a9amain bar|r"},{id="eviscerate",where="Key |cff7fd4ff2|r |cff9a9a9amain bar|r"},{id="throw",where="Key |cff7fd4ff6|r |cff9a9a9amain bar|r"},{id="shadowmeld",where="|cff7fd4ffShift|r + |cff7fd4ff7|r |cff9a9a9abottom left bar|r"},{id="eluneslight",where="Key |cff7fd4ff0|r |cff9a9a9amain bar|r"},{id="hearth",where="Right bar, button |cffffd20010|r |cff9a9a9acounting from the top|r"},{id="food1",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","First time? Turn on the extra bars first: |cffffd200Action Bars tab|r > How to set this up in game.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Teldrassil",x=58.7,y=44.3,label="You start here, under Aldrassil"}},quests={"Action bar","How to set this up in game","energy"}},
  {kind="quest",chapter=1,lv="1",lo=1,hi=1,place="Shadowglen",title="Your first quest",todo={"Talk to |cffffd200Conservator Ilthalaine|r, the night elf right in front of you. He has a yellow |cffffd200!|r over his head. Accept |cffffd200The Balance of Nature|r.","Walk out into the glade and kill |cffffd2007 young nightsabers|r and |cffffd2004 young thistle boars|r.","Go back to Ilthalaine. He now has a yellow |cffffd200?|r. Talk to him to turn in the quest. Then take |cffffd200The Balance of Nature|r part 2 and your rogue quest, |cffffd200Encrypted Sigil|r."},done="you've handed in |cffffd200The Balance of Nature|r, and its second part and |cffffd200Encrypted Sigil|r are in your |cffe2c6ff|Hwfw:24|hquest log|h|r.",tip="How to fight: click a nightsaber to target it, walk up to it and press |cff7fd4ff1|r. Your character also hits by itself while you stand next to the enemy.",pins={{zone="Teldrassil",x=58.7,y=44.3,label="Conservator Ilthalaine"},{zone="Teldrassil",x=60.5,y=48.5,label="Young nightsabers and thistle boars"}},quests={"Conservator Ilthalaine","The Balance of Nature","Encrypted Sigil"}},
  {kind="train",chapter=1,lv="1–2",lo=1,hi=2,place="Shadowglen",title="Meet your trainer",todo={"|cffffd200Encrypted Sigil|r sends you to |cffffd200Frahun Shadewhisper|r, the rogue |cffe2c6ff|Hwfw:34|htrainer|h|r inside the big tree, Aldrassil. Walk up the ramp into the tree to find him.","Turn it in and learn |cffffd200|cffe2c6ff|Hwfw:30|hStealth|h|r|r. Put it on key |cff7fd4ff=|r.","|cffe2c6ff|Hwfw:30|hStealth|h|r makes you almost invisible. You walk slower, and enemies only see you when you're very close. Any attack breaks it."},done="you've handed in |cffffd200Encrypted Sigil|r and |cffe2c6ff|Hwfw:30|hStealth|h|r is on key |cff7fd4ff=|r.",tip="After every fight, if your health is low, sit and eat (|cff7fd4ffAlt|r + |cff7fd4ff2|r) before the next one. It saves you from dying.",bars={head="Action bar · when you next visit the trainer",rows={{id="stealth",where="Key |cff7fd4ff=|r |cff9a9a9amain bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Teldrassil",x=59.6,y=38.6,label="Frahun Shadewhisper (inside Aldrassil)"},{zone="Teldrassil",x=58.7,y=44.3,label="Ilthalaine"}},quests={"Encrypted Sigil","Frahun Shadewhisper","Stealth"}},
  {kind="quest",chapter=1,lv="2–4",lo=2,hi=4,place="Shadowglen",title="Grells, boars and a friend in need",todo={"Take |cffffd200The Woodland Protector|r from |cffffd200Melithar Staghelm|r at the foot of Aldrassil and talk to |cffffd200Tarindrella|r, the dryad just south of the tree. She gives part 2: kill grells and grellkin west of the tree for |cffffd200Fel Moss|r, then hand it back to her.","On the way, finish |cffffd200The Balance of Nature|r part 2: kill |cffffd2007 mangy nightsabers|r and |cffffd2007 thistle boars|r. Hand it in to Ilthalaine.","Take |cffffd200Webwood Venom|r from |cffffd200Gilshalan Windwalker|r at the bottom of the ramp into Aldrassil. You do it in the next step.","|cffffd200Dirania Silvershine|r, by the tree, gives |cffffd200A Good Friend|r. Walk north-west to |cffffd200Iverron|r at the mouth of Shadowthread Cave. He gives |cffffd200A Friend in Need|r: go back to Dirania and hand it in. She gives |cffffd200Iverron's Antidote|r."},done="you've handed in both parts of |cffffd200The Woodland Protector|r and |cffffd200The Balance of Nature|r part 2, and Dirania has given you |cffffd200Iverron's Antidote|r.",stuck="Fight grells and thistle boars near Aldrassil until you're level 4.",tip="Grells stand in small groups. Attack the one at the edge so its friends don't join in.",pins={{zone="Teldrassil",x=59.9,y=42.5,label="Melithar Staghelm"},{zone="Teldrassil",x=57.8,y=45.2,label="Tarindrella"},{zone="Teldrassil",x=55,y=42,label="Grells"},{zone="Teldrassil",x=60.9,y=42,label="Dirania Silvershine"},{zone="Teldrassil",x=54.6,y=33,label="Iverron"}},quests={"The Woodland Protector","Melithar Staghelm","Tarindrella","Fel Moss","The Balance of Nature","Webwood Venom","Gilshalan Windwalker","Dirania Silvershine","A Good Friend","Iverron","A Friend in Need","Iverron's Antidote"}},
  {kind="train",chapter=1,lv="4",lo=4,hi=4,place="Frahun Shadewhisper (trainer)",title="Level 4: Backstab",todo={"Go back to Frahun and learn |cffffd200Backstab|r and |cffffd200Pick Pocket|r.","Put Backstab on |cff7fd4ffShift|r + |cff7fd4ff2|r. It only works |cffffd200from behind|r the enemy, and only with a dagger. You start with a dagger, so: |cffe2c6ff|Hwfw:30|hStealth|h|r, sneak behind an enemy, Backstab.","Pick Pocket steals a little money from humanoids while you're in |cffe2c6ff|Hwfw:30|hStealth|h|r. Put it on the right bar and use it on every |cffe2c6ff|Hwfw:16|hhumanoid|h|r before you attack."},done="Backstab is on |cff7fd4ffShift|r + |cff7fd4ff2|r and Pick Pocket is on your right bar.",bars={head="Action bar",rows={{id="backstab",where="|cff7fd4ffShift|r + |cff7fd4ff2|r |cff9a9a9abottom left bar|r"},{id="pickpocket",where="Right bar, button |cffffd2005|r |cff9a9a9acounting from the top|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Teldrassil",x=59.6,y=38.6,label="Frahun Shadewhisper (rogue trainer)"}},quests={"Backstab","Pick Pocket","from behind"}},
  {kind="quest",chapter=1,lv="4–5",lo=4,hi=5,place="Shadowglen",title="Spiders, the antidote and the egg",todo={"Gather the things for |cffffd200Iverron's Antidote|r: |cffffd2007 Hyacinth Mushrooms|r (they grow on the ground around the grell camps, and grells can drop them), |cffffd2004 Moonpetal Lilies|r (white flowers around the ponds north-west of Aldrassil) and |cffffd2001 Webwood Ichor|r (from a webwood spider).","Kill webwood spiders outside |cffffd200Shadowthread Cave|r for |cffffd20010 Webwood Venom Sacs|r (Webwood Venom).","Bring the ingredients to Dirania. She gives you the antidote: take it to Iverron at the cave mouth |cffffd200before the timer runs out|r. If time runs out, abandon the quest (|cffe2c6ff|Hwfw:24|hquest log|h|r |cff7fd4ffL|r, |cffffd200Abandon|r) and take it again from Dirania.","Hand in Webwood Venom to Gilshalan and take |cffffd200Webwood Egg|r. In the cave, take the middle path at the first split, go straight, then follow the path up and round to the right. Pick up an egg and bring it back to Gilshalan."},done="you've handed in |cffffd200Iverron's Antidote|r to Iverron, and |cffffd200Webwood Venom|r and |cffffd200Webwood Egg|r to Gilshalan.",stuck="Fight the webwood spiders outside the cave until you're level 5.",tip="In caves, enemies stand close together. Fight them one at a time and step back so you don't |cffe2c6ff|Hwfw:22|hpull|h|r their friends.",pins={{zone="Teldrassil",x=57,y=32.5,label="Shadowthread Cave (webwood spiders)"},{zone="Teldrassil",x=54.6,y=33,label="Iverron"},{zone="Teldrassil",x=56.5,y=37.5,label="Ponds north-west of the tree (Moonpetal Lilies)"},{zone="Teldrassil",x=60.9,y=42,label="Dirania Silvershine"},{zone="Teldrassil",x=59.6,y=38.6,label="Gilshalan (foot of the ramp)"}},quests={"Iverron's Antidote","Shadowthread Cave","before the timer runs out","Abandon","Webwood Egg"}},
  {kind="travel",chapter=1,lv="5–6",lo=5,hi=6,place="Shadowglen",title="Leave Shadowglen",todo={"Gilshalan gives |cffffd200Tenaron's Summons|r. Walk all the way up Aldrassil to |cffffd200Tenaron Stormgrip|r at the top and hand it in.","Tenaron gives |cffffd200Crown of the Earth|r. Go to the |cffffd200moonwell|r north of the tree, use the empty phial from your bag while you stand at the well, and bring the full phial back to him. Take the next part: it goes to Corithras Moonrage in Dolanaar.","Take |cffffd200Dolanaar Delivery|r from |cffffd200Porthannius|r, on the path out of the glade.","Follow the road south out of the glade to the town of |cffffd200Dolanaar|r."},done="you've reached Dolanaar with |cffffd200Dolanaar Delivery|r and |cffffd200Crown of the Earth|r in your |cffe2c6ff|Hwfw:24|hquest log|h|r.",stuck="Fight nightsabers and boars along the road until you're level 6.",pins={{zone="Teldrassil",x=59.6,y=38.6,label="Tenaron Stormgrip (top of Aldrassil)"},{zone="Teldrassil",x=62.5,y=32.5,label="Moonwell"},{zone="Teldrassil",x=61.2,y=47.6,label="Porthannius"},{zone="Teldrassil",x=55.6,y=59.8,label="Dolanaar"}},quests={"Tenaron's Summons","Tenaron Stormgrip","Crown of the Earth","moonwell","Dolanaar Delivery","Porthannius","Dolanaar"}},
  {kind="home",chapter=2,lv="6",lo=6,hi=6,place="Dolanaar",title="Make Dolanaar your home",todo={"Find |cffffd200Innkeeper Keldamyr|r and choose |cffffd200Make this |cffe2c6ff|Hwfw:17|hinn|h|r your home|r. Hand |cffffd200Dolanaar Delivery|r to him too.","Your |cffffd200|cffe2c6ff|Hwfw:15|hHearthstone|h|r|r (in your bag) now teleports you back here. It has a 1 hour |cffe2c6ff|Hwfw:5|hcooldown|h|r.","Hand |cffffd200Crown of the Earth|r to |cffffd200Corithras Moonrage|r and take the next part: fill a phial at the moonwell in |cffffd200Starbreeze Village|r.","Better food: from level 5, buy |cffffd200Tel'Abim Bananas|r from a food |cffe2c6ff|Hwfw:35|hvendor|h|r (ask a guard) and put them on |cff7fd4ffAlt|r + |cff7fd4ff2|r."},done="your |cffe2c6ff|Hwfw:15|hHearthstone|h|r says |cffffd200Dolanaar|r when you hover over it, and you've handed in |cffffd200Dolanaar Delivery|r and |cffffd200Crown of the Earth|r.",tip="Always log out inside an |cffe2c6ff|Hwfw:17|hinn|h|r. You'll get bonus |cffe2c6ff|Hwfw:36|hXP|h|r (called |cffe2c6ff|Hwfw:28|hrested XP|h|r) when you come back.",bars={head="Action bar · when you next visit the trainer",rows={{id="food2",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Shiny Red Apple"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Teldrassil",x=55.6,y=59.8,label="Innkeeper Keldamyr"},{zone="Teldrassil",x=56.1,y=61.7,label="Corithras Moonrage"}},quests={"Innkeeper Keldamyr","Make this inn your home","Dolanaar Delivery","Hearthstone","Crown of the Earth","Corithras Moonrage","Starbreeze Village","Tel'Abim Bananas"}},
  {kind="train",chapter=2,lv="6",lo=6,hi=6,place="Jannok Breezesong (trainer, Dolanaar)",title="Level 6: Gouge",todo={"Dolanaar has its own rogue |cffe2c6ff|Hwfw:34|htrainer|h|r, |cffffd200Jannok Breezesong|r. Learn |cffffd200Gouge|r and put it on key |cff7fd4ff4|r.","Gouge stuns the enemy for a few seconds. Any hit wakes it up again, so use the time to get behind it, or to run away."},done="Gouge is on key |cff7fd4ff4|r.",tip="Trick to learn now: Gouge, walk behind the enemy, Backstab. It only works while you have a dagger in your main hand.",bars={head="Action bar",rows={{id="gouge",where="Key |cff7fd4ff4|r |cff9a9a9amain bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Teldrassil",x=56.4,y=60.1,label="Jannok Breezesong (rogue trainer)"}},quests={"Jannok Breezesong","Gouge"}},
  {kind="quest",chapter=2,lv="6–7",lo=6,hi=7,place="Dolanaar",title="Grab every quest in town",todo={"|cffffd200Athridas Bearmantle|r: |cffffd200A Troubling Breeze|r. Talk to Gaerolas in Starbreeze Village.","|cffffd200Tallonkai Swiftroot|r: |cffffd200The Emerald Dreamcatcher|r. Find it in Starbreeze Village.","|cffffd200Zenn Foulhoof|r, the satyr on the road just east of town: |cffffd200Zenn's Bidding|r. He wants nightsaber pelts, owl feathers and spider silk, so kill nightsabers, strigid owls and webwood spiders as you go.","Press |cff7fd4ffL|r to open your |cffe2c6ff|Hwfw:24|hquest log|h|r. Each quest says how many you need and where to go. More quests open in town once you finish these."},done="your |cffe2c6ff|Hwfw:24|hquest log|h|r (|cff7fd4ffL|r) has |cffffd200A Troubling Breeze|r, |cffffd200The Emerald Dreamcatcher|r, |cffffd200Crown of the Earth|r and |cffffd200Zenn's Bidding|r.",pins={{zone="Teldrassil",x=55.6,y=59.8,label="Dolanaar"},{zone="Teldrassil",x=60.5,y=56.3,label="Zenn Foulhoof"}},quests={"Athridas Bearmantle","A Troubling Breeze","Tallonkai Swiftroot","The Emerald Dreamcatcher","Zenn Foulhoof","Zenn's Bidding"}},
  {kind="quest",chapter=2,lv="7",lo=7,hi=7,place="Starbreeze Village",title="Starbreeze Village",todo={"Go east to |cffffd200Starbreeze Village|r. |cffffd200Gaerolas Talvethren|r is on the top floor of the biggest house: hand in |cffffd200A Troubling Breeze|r and take |cffffd200Gnarlpine Corruption|r. You only need to take his message back to Athridas.","|cffffd200The Emerald Dreamcatcher|r is in the dresser of the smaller house.","Fill the phial at the |cffffd200Starbreeze moonwell|r (Crown of the Earth).","Back in Dolanaar, hand it all in: Gnarlpine Corruption to Athridas, the Dreamcatcher to Tallonkai and the phial to Corithras. Give the pelts, feathers and silk to Zenn on the road. Take every new quest they offer."},done="you've handed in |cffffd200A Troubling Breeze|r, |cffffd200Gnarlpine Corruption|r, |cffffd200The Emerald Dreamcatcher|r, the Starbreeze phial and |cffffd200Zenn's Bidding|r.",stuck="Fight nightsabers and owls between Dolanaar and Starbreeze until you're level 7.",pins={{zone="Teldrassil",x=66.3,y=58.5,label="Starbreeze Village"},{zone="Teldrassil",x=60.5,y=56.3,label="Zenn Foulhoof"},{zone="Teldrassil",x=55.6,y=59.8,label="Dolanaar"}},quests={"Starbreeze Village","Gaerolas Talvethren","A Troubling Breeze","Gnarlpine Corruption","The Emerald Dreamcatcher","Starbreeze moonwell"}},
  {kind="quest",chapter=2,lv="7–8",lo=7,hi=8,place="Around Dolanaar",title="Ferocitas, Lord Melenas and the fel cones",todo={"Tallonkai gives |cffffd200Ferocitas the Dream Eater|r. The furbolg camp is just north of Starbreeze: kill the Gnarlpine Mystics your |cffe2c6ff|Hwfw:24|hquest log|h|r asks for and |cffffd200Ferocitas|r. Right-click the necklace Ferocitas drops to get |cffffd200Tallonkai's Jewel|r, then bring it to Tallonkai.","Tallonkai then gives |cffffd200Twisted Hatred|r: kill the satyr |cffffd200Lord Melenas|r at the back of the |cffffd200Fel Rock|r cave, in the hills just north-west of Dolanaar, and bring his head back.","|cffffd200Syral Bladeleaf|r in Dolanaar now gives |cffffd200Seek Redemption!|r: pick up |cffffd2003 Fel Cones|r (they lie on the ground under the big trees around Dolanaar) and give them to Zenn Foulhoof. Also take |cffffd200Denalan's Earth|r from Syral for the next step."},done="you've handed in |cffffd200Ferocitas the Dream Eater|r, |cffffd200Twisted Hatred|r and |cffffd200Seek Redemption!|r, and you're level 8.",stuck="Fight the Gnarlpine furbolgs north of Starbreeze until you are.",tip="Furbolgs come in groups. Use |cffe2c6ff|Hwfw:30|hStealth|h|r to sneak past the ones you don't need.",pins={{zone="Teldrassil",x=69.4,y=53.4,label="Ferocitas the Dream Eater (furbolg camp)"},{zone="Teldrassil",x=51.2,y=50.8,label="Fel Rock (Lord Melenas)"},{zone="Teldrassil",x=55.6,y=59.8,label="Dolanaar"},{zone="Teldrassil",x=60.5,y=56.3,label="Zenn Foulhoof"}},quests={"Ferocitas the Dream Eater","Ferocitas","Tallonkai's Jewel","Twisted Hatred","Lord Melenas","Fel Rock","Syral Bladeleaf","Seek Redemption!","Denalan's Earth"}},
  {kind="train",chapter=2,lv="8",lo=8,hi=8,place="Jannok Breezesong (trainer, Dolanaar)",title="Level 8: Evasion",todo={"Learn |cffffd200Evasion|r and put it on key |cff7fd4ff8|r.","Evasion makes you dodge most attacks for a while. Press it when two or more enemies attack you at once, or when your health drops fast."},done="Evasion is on key |cff7fd4ff8|r.",bars={head="Action bar",rows={{id="evasion",where="Key |cff7fd4ff8|r |cff9a9a9amain bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},pins={{zone="Teldrassil",x=56.4,y=60.1,label="Jannok Breezesong (rogue trainer)"}},quests={"Evasion"}},
  {kind="quest",chapter=2,lv="8–10",lo=8,hi=10,place="Lake Al'Ameth",title="Denalan's seeds",todo={"Go south to |cffffd200Denalan|r, who camps on the north-east shore of |cffffd200Lake Al'Ameth|r. Hand in |cffffd200Denalan's Earth|r.","|cffffd200Timberling Seeds|r: kill timberlings along the lake shore for their seeds. |cffffd200Timberling Sprouts|r: pick up the little sprouts growing on the ground in the same area. Hand both back to Denalan.","Denalan then gives |cffffd200Rellian Greenspyre|r. Keep it: you hand it in in Darnassus.","Skip |cffffd200Oakenscowl|r unless you have a group. He's an |cffffd200|cffe2c6ff|Hwfw:8|helite|h|r|r."},done="you've handed in |cffffd200Denalan's Earth|r, |cffffd200Timberling Seeds|r and |cffffd200Timberling Sprouts|r to Denalan, and you're level 10.",stuck="Fight timberlings around the lake until you are.",talents={"Level 10–11: |cffffd200Efficient Strikes (Combat tab)|r, click it 2 times (once per level). Sinister Strike costs less energy."},pins={{zone="Teldrassil",x=60.9,y=68.5,label="Denalan"},{zone="Teldrassil",x=56,y=72,label="Timberlings"},{zone="Teldrassil",x=53.8,y=75.1,label="Oakenscowl's cave (elite)"}},quests={"Denalan","Lake Al'Ameth","Denalan's Earth","Timberling Seeds","Timberling Sprouts","Rellian Greenspyre","Oakenscowl","elite"}},
  {kind="train",chapter=2,lv="10",lo=10,hi=10,place="Jannok Breezesong (trainer, Dolanaar)",title="Level 10: Slice and Dice and your first talent",todo={"Learn |cffffd200Slice and Dice|r, |cffffd200Sprint|r, |cffffd200Sap|r and |cffffd200Dual Wield|r. Dual Wield lets you hold a weapon in each hand. It works by itself, no button.","Put Slice and Dice on key |cff7fd4ff3|r and Sprint on key |cff7fd4ff7|r. Sap goes on |cff7fd4ffShift|r + |cff7fd4ff=|r.","Press |cff7fd4ffN|r to open talents. Click the |cffffd200Combat|r tab and put your point into |cffffd200Efficient Strikes|r: Sinister Strike costs less |cffe2c6ff|Hwfw:10|henergy|h|r.","Jannok also gives your rogue quest, |cffffd200The Apple Falls|r. It sends you to Syurna in Darnassus."},done="Slice and Dice is on |cff7fd4ff3|r, Sprint on |cff7fd4ff7|r, Sap on |cff7fd4ffShift|r + |cff7fd4ff=|r, your |cffe2c6ff|Hwfw:32|htalent|h|r point is spent, and |cffffd200The Apple Falls|r is in your |cffe2c6ff|Hwfw:24|hquest log|h|r.",tip="New fight: Sinister Strike twice, Slice and Dice (you attack faster), then Sinister Strike until you have 3 to 5 |cffe2c6ff|Hwfw:4|hcombo points|h|r, then Eviscerate. Keep Slice and Dice running.",bars={head="Action bar",rows={{id="slicedice",where="Key |cff7fd4ff3|r |cff9a9a9amain bar|r"},{id="sprint",where="Key |cff7fd4ff7|r |cff9a9a9amain bar|r"},{id="sap",where="|cff7fd4ffShift|r + |cff7fd4ff=|r |cff9a9a9abottom left bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 10–11: |cffffd200Efficient Strikes (Combat tab)|r, click it 2 times (once per level). Sinister Strike costs less energy."},pins={{zone="Teldrassil",x=56.4,y=60.1,label="Jannok Breezesong (rogue trainer)"}},quests={"Slice and Dice","Sprint","Sap","Dual Wield","Combat","Efficient Strikes","The Apple Falls"}},
  {kind="travel",chapter=3,lv="10",lo=10,hi=10,place="Darnassus",title="Visit Darnassus",todo={"Follow the road west from Dolanaar to the city of |cffffd200Darnassus|r. On the road, |cffffd200Moon Priestess Amara|r gives |cffffd200The Road to Darnassus|r: kill the Gnarlpine Ambushers that jump out along the road. Hand it back to her.","Find the rogue trainers in the |cffffd200Cenarion Enclave|r (click any guard and they mark it on your map). Hand |cffffd200The Apple Falls|r to |cffffd200Syurna|r and take |cffffd200Destiny Calls|r. You do it at level 11–12.","Hand in |cffffd200Rellian Greenspyre|r to Rellian (ask a guard where he is).","Learn |cffffd200First Aid|r and |cffffd200Cooking|r. Rogues can't heal themselves, so bandages made from cloth are your best friend. Skinning and Leatherworking are good main professions for a rogue: see the |cffffd200Professions page|r (on the website).","Buy |cffffd200Rough Sharpening Stones|r at the |cffe2c6ff|Hwfw:2|hauction house|h|r. Rub one on each weapon (click the stone, then the weapon) for extra damage."},done="you've learned First Aid and Cooking, handed in |cffffd200The Apple Falls|r and |cffffd200Rellian Greenspyre|r, and |cffffd200Destiny Calls|r is in your |cffe2c6ff|Hwfw:24|hquest log|h|r.",tip="Bandages: open First Aid (|cffe2c6ff|Hwfw:29|hspellbook|h|r, |cff7fd4ffP|r), make |cffffd200Linen Bandages|r from the Linen Cloth that humanoids drop, and put them on |cff7fd4ffAlt|r + |cff7fd4ff1|r. Bandage after a fight while you eat.",bars={head="Action bar · when you next visit the trainer",rows={{id="firstaid",where="Right bar, button |cffffd2009|r |cff9a9a9acounting from the top|r"},{id="bandage1",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r"},{id="stone1",where="Right bar, button |cffffd2004|r |cff9a9a9acounting from the top|r"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 10–11: |cffffd200Efficient Strikes (Combat tab)|r, click it 2 times (once per level). Sinister Strike costs less energy."},pins={{zone="Teldrassil",x=39,y=49,label="The road west to Darnassus"},{zone="Darnassus",x=63,y=61,label="You come in here"},{zone="Darnassus",x=37,y=22,label="Rogue trainers and Syurna (Cenarion Enclave)"},{zone="Darnassus",x=57.6,y=46.7,label="Ilyenia Moonfire (weapon trainer)"}},quests={"Darnassus","Moon Priestess Amara","The Road to Darnassus","Cenarion Enclave","The Apple Falls","Syurna","Destiny Calls","Rellian Greenspyre","First Aid","Cooking","Rough Sharpening Stones"}},
  {kind="quest",chapter=3,lv="10–11",lo=10,hi=11,place="Western Teldrassil",title="Ban'ethil Barrow Den",todo={"Back in Dolanaar, take |cffffd200The Relics of Wakening|r and |cffffd200Ursal the Mauler|r from Athridas and the next |cffffd200Crown of the Earth|r phial from Corithras.","|cffffd200Ban'ethil Barrow Den|r is the furbolg cave west of Dolanaar. |cffffd200The Relics of Wakening|r: open the chests inside for the |cffffd200Raven Claw Talisman|r, |cffffd200Black Feather Quill|r, |cffffd200Sapphire of Sky|r and |cffffd200Rune of Nesting|r.","Inside the den, the ghost |cffffd200Oben Rageclaw|r gives |cffffd200The Sleeping Druid|r: kill Gnarlpine shamans until one drops a |cffffd200Shaman Voodoo Charm|r (it can take a while). Then |cffffd200Druid of the Claw|r: use the charm on the bear at the bottom of the den, kill it, and go back to Oben.","Fill the phial at the moonwell by the |cffffd200Pools of Arlithrien|r, south-west of the den (Crown of the Earth). |cffffd200Ursal the Mauler|r is the furbolg leader in the camps there: leave him until you're level 11, he hits hard."},done="you've finished |cffffd200The Relics of Wakening|r and |cffffd200Druid of the Claw|r, and the Pools of Arlithrien phial is full.",stuck="Fight the furbolgs around Ban'ethil Barrow until you're level 11.",talents={"Level 10–11: |cffffd200Efficient Strikes (Combat tab)|r, click it 2 times (once per level). Sinister Strike costs less energy."},pins={{zone="Teldrassil",x=44.9,y=61.6,label="Oben Rageclaw (inside the den)"},{zone="Teldrassil",x=44.5,y=59.5,label="Ban'ethil Barrow Den"},{zone="Teldrassil",x=42,y=67,label="Pools of Arlithrien (moonwell, Ursal)"},{zone="Teldrassil",x=55.6,y=59.8,label="Dolanaar"}},quests={"The Relics of Wakening","Ursal the Mauler","Crown of the Earth","Ban'ethil Barrow Den","Raven Claw Talisman","Black Feather Quill","Sapphire of Sky","Rune of Nesting","Oben Rageclaw","The Sleeping Druid","Shaman Voodoo Charm","Druid of the Claw","Pools of Arlithrien"}},
  {kind="quest",chapter=3,lv="11–12",lo=11,hi=12,place="Oracle Glade",title="Rogue quest: Sethir's journal",todo={"Ride north past Darnassus to the |cffffd200Oracle Glade|r. On the way, fill the next phial at the moonwell on the road north of Darnassus (Crown of the Earth).","|cffffd200Destiny Calls|r: |cffffd200Sethir the Ancient|r, a level 12 satyr, stands on a branch north of the Oracle Glade. Go north of the glade and follow the wooden wall west. In |cffe2c6ff|Hwfw:30|hStealth|h|r, walk up behind him, use |cffffd200Pick Pocket|r to steal |cffffd200Sethir's Journal|r, and walk away. Don't fight him: he has helpers.","Find |cffffd200Mist|r, the lost nightsaber cub, at the far north-west point of the island. Talk to her and lead her back to |cffffd200Sentinel Arynia Cloudsbreak|r at the Oracle Glade.","Back in Dolanaar: hand in |cffffd200The Relics of Wakening|r and |cffffd200Ursal the Mauler|r to Athridas and the phial to Corithras. Take the last part of |cffffd200Crown of the Earth|r: it goes to Arch Druid Fandral Staghelm in Darnassus."},done="|cffffd200Sethir's Journal|r is in your bags, Mist is home, you've handed in your Dolanaar quests, and you're level 12.",stuck="Fight the furbolgs at the Pools of Arlithrien until you are.",tip="If Sethir sees you, run and come back when you're level 12. The higher your level, the closer you can sneak.",talents={"Level 10–11: |cffffd200Efficient Strikes (Combat tab)|r, click it 2 times (once per level). Sinister Strike costs less energy.","Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Teldrassil",x=38.3,y=34.4,label="Sentinel Arynia Cloudsbreak (Oracle Glade)"},{zone="Teldrassil",x=37,y=22,label="Sethir the Ancient (on a branch)"},{zone="Teldrassil",x=31.5,y=31.6,label="Mist (nightsaber cub)"},{zone="Teldrassil",x=55.6,y=59.8,label="Dolanaar"}},quests={"Oracle Glade","Destiny Calls","Sethir the Ancient","Pick Pocket","Sethir's Journal","Mist","Sentinel Arynia Cloudsbreak","The Relics of Wakening","Ursal the Mauler","Crown of the Earth"}},
  {kind="train",chapter=3,lv="12",lo=12,hi=12,place="Jannok Breezesong (trainer, Dolanaar)",title="Level 12: Kick",todo={"Learn |cffffd200Kick|r and |cffffd200Parry|r. Parry works by itself.","Put Kick on key |cff7fd4ff5|r. When an enemy is casting a spell (you'll see a cast bar under its name), press it to stop the spell.","Spend your |cffe2c6ff|Hwfw:32|htalent|h|r points (|cff7fd4ffN|r). The Talents tab of this guide tells you which one."},done="Kick is on key |cff7fd4ff5|r and your |cffe2c6ff|Hwfw:32|htalent|h|r points are spent.",tip="From now on, train every even level and spend a |cffe2c6ff|Hwfw:32|htalent|h|r point every level.",bars={head="Action bar",rows={{id="kick",where="Key |cff7fd4ff5|r |cff9a9a9amain bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Teldrassil",x=56.4,y=60.1,label="Jannok Breezesong (Dolanaar)"},{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Kick","Parry"}},
  {kind="travel",chapter=3,lv="12",lo=12,hi=12,place="Darnassus > Rut'theran Village",title="Your dagger, then fly to Darkshore",todo={"In Darnassus, hand in |cffffd200Destiny Calls|r to Syurna. Equip the |cffffd200Blade of Cunning|r (right-click it in your bags): a much better dagger than the one you started with.","Hand in |cffffd200Crown of the Earth|r to |cffffd200Arch Druid Fandral Staghelm|r at the top of the Cenarion Enclave's main building. Take |cffffd200Grove of the Ancients|r from him: you hand it in to Onu in Darkshore.","Take the quest |cffffd200Nessa Shadowsong|r near the Darnassus entrance and step into the pink portal to |cffffd200Rut'theran Village|r at the bottom of the tree.","Turn in to Nessa and take |cffffd200The Bounty of Teldrassil|r. Talk to |cffffd200Vesprystus|r, the hippogryph master, and take |cffffd200Flight to Auberdine|r. Your first flight is free: fly to |cffffd200Auberdine|r in Darkshore."},done="the |cffffd200Blade of Cunning|r is in your main hand and you've landed in Auberdine.",tip="Your talents are for Combat, which likes swords, maces, axes and fist weapons. Until you find a good one, a strong dagger is fine.",talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Darnassus",x=37,y=22,label="Syurna and Fandral Staghelm (Cenarion Enclave)"},{zone="Teldrassil",x=56.3,y=92.4,label="Nessa Shadowsong"},{zone="Teldrassil",x=58.4,y=94,label="Vesprystus (flight master)"},{zone="Darkshore",x=36.3,y=45.6,label="Auberdine: you land here"}},quests={"Destiny Calls","Blade of Cunning","Crown of the Earth","Arch Druid Fandral Staghelm","Grove of the Ancients","Nessa Shadowsong","Rut'theran Village","The Bounty of Teldrassil","Vesprystus","Flight to Auberdine","Auberdine"}},
  {kind="home",chapter=4,lv="12",lo=12,hi=12,place="Auberdine",title="Your new home: Auberdine",todo={"Hand in |cffffd200Flight to Auberdine|r to Laird. Make the |cffe2c6ff|Hwfw:17|hinn|h|r your home and talk to the flight master so you can fly here later.","Take every quest in town: |cffffd200Buzzbox 827|r (Wizbang Cranktoggle, the gnome), |cffffd200Washed Ashore|r (Gwennyth Bly'Leggonde), |cffffd200Plagued Lands|r (Tharnariun Treetender), |cffffd200How Big a Threat?|r, |cffffd200Bashal'Aran|r and |cffffd200Tools of the Highborne|r (Thundris Windweaver), |cffffd200The Fall of Ameth'Aran|r (Sentinel Tysha Moonblade), |cffffd200The Red Crystal|r and |cffffd200Cave Mushrooms|r.","Your |cffe2c6ff|Hwfw:24|hquest log|h|r (|cff7fd4ffL|r) says how many of each thing you need. Check it before you leave town."},done="Auberdine is your home and the quests above are in your log.",tip="There's no rogue |cffe2c6ff|Hwfw:34|htrainer|h|r here. Every two levels, fly back to Rut'theran and take the portal up to Darnassus to train.",talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Darkshore",x=37,y=44.1,label="Innkeeper Shaussiy"},{zone="Darkshore",x=36.3,y=45.6,label="Flight master"}},quests={"Flight to Auberdine","Buzzbox 827","Washed Ashore","Plagued Lands","How Big a Threat?","Bashal'Aran","Tools of the Highborne","The Fall of Ameth'Aran","The Red Crystal","Cave Mushrooms"}},
  {kind="quest",chapter=4,lv="12–13",lo=12,hi=13,place="Darkshore beach",title="The beach and the hills by town",todo={"|cffffd200Buzzbox 827|r: kill crawlers (crabs) on the beach just south of town for their legs. Hand them in at the |cffffd200Buzzbox 827|r machine on the beach and take |cffffd200Buzzbox 411|r.","|cffffd200Washed Ashore|r: search the big sea creature skeleton on the beach to the south. Hand it in to Gwennyth and take part 2. Your |cffe2c6ff|Hwfw:24|hquest log|h|r says where to look next.","|cffffd200How Big a Threat?|r: find the furbolg camp east of the road, look at it, and report back. Take part 2: it asks you to kill those furbolgs (next steps).","|cffffd200Plagued Lands|r: Tharnariun gives you a trap item. Find a |cffffd200rabid thistle bear|r in the hills east of town, use the item to put the trap down, and |cffe2c6ff|Hwfw:22|hpull|h|r the bear onto it. Hand it in and take |cffffd200Cleansing of the Infected|r."},done="you've handed in |cffffd200Buzzbox 827|r, |cffffd200Washed Ashore|r, |cffffd200How Big a Threat?|r and |cffffd200Plagued Lands|r.",stuck="Fight crawlers on the beach until you're level 13.",talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Darkshore",x=36.7,y=46.3,label="Buzzbox 827"},{zone="Darkshore",x=36.5,y=51,label="Beached Sea Creature"},{zone="Darkshore",x=39,y=52,label="Furbolg camp"}},quests={"Buzzbox 827","Buzzbox 411","Washed Ashore","How Big a Threat?","Plagued Lands","rabid thistle bear","Cleansing of the Infected"}},
  {kind="quest",chapter=4,lv="13–14",lo=13,hi=14,place="Bashal'Aran and Ameth'Aran",title="The two ruins",todo={"|cffffd200Bashal'Aran|r: follow the road north-east to the ruins and talk to the ghost |cffffd200Asterion|r on the hill. He wants |cffffd2008 Grell Earrings|r (kill the wild grells around the ruins), then the |cffffd200Ancient Moonstone Seal|r: kill the satyrs there until one drops it.","Take the seal to the blue flame in |cffffd200Ameth'Aran|r, the ruins south-east of town, to destroy it. Then go back to Asterion.","While you're in Ameth'Aran: |cffffd200Tools of the Highborne|r (kill the Highborne spirits for 7 Highborne Relics) and |cffffd200The Fall of Ameth'Aran|r (find and read the stone tablets in the ruins). Hand both in in Auberdine.","|cffffd200The Red Crystal|r: find the big red crystal in the hills east of town. It leads to |cffffd200As Water Cascades|r (fill the bottle at the Auberdine moonwell and bring it to the crystal) and then |cffffd200The Fragments Within|r."},done="you've finished the |cffffd200Bashal'Aran|r chain, |cffffd200Tools of the Highborne|r, |cffffd200The Fall of Ameth'Aran|r and |cffffd200The Red Crystal|r chain, and you're level 14.",stuck="Fight the grells and satyrs at Bashal'Aran until you are.",tip="Skip |cffffd200For Love Eternal|r (Cerellean Whiteclaw) for now. Its target is too strong at this level.",talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Darkshore",x=44.2,y=36.3,label="Asterion (Bashal'Aran)"},{zone="Darkshore",x=42.5,y=62,label="Ameth'Aran (blue flame, spirits, tablets)"},{zone="Darkshore",x=47,y=49,label="The Red Crystal"}},quests={"Bashal'Aran","Asterion","Ancient Moonstone Seal","Ameth'Aran","Tools of the Highborne","The Fall of Ameth'Aran","The Red Crystal","As Water Cascades","The Fragments Within"}},
  {kind="train",chapter=4,lv="14",lo=14,hi=14,place="Darnassus (fly)",title="Level 14: Garrote and Expose Armor",todo={"Fly to Rut'theran, take the portal up to Darnassus, and learn everything you can afford.","|cffffd200Garrote|r (|cff7fd4ffShift|r + |cff7fd4ff3|r) is an |cffe2c6ff|Hwfw:20|hopener|h|r: from |cffe2c6ff|Hwfw:30|hStealth|h|r, behind the enemy. It makes it bleed for a while.","|cffffd200Expose Armor|r (|cff7fd4ffShift|r + |cff7fd4ff9|r) makes an enemy take more damage. Only worth it on enemies that live a long time, like bosses."},done="Garrote is on |cff7fd4ffShift|r + |cff7fd4ff3|r and Expose Armor on |cff7fd4ffShift|r + |cff7fd4ff9|r.",bars={head="Action bar",rows={{id="garrote",where="|cff7fd4ffShift|r + |cff7fd4ff3|r |cff9a9a9abottom left bar|r"},{id="exposearmor",where="|cff7fd4ffShift|r + |cff7fd4ff9|r |cff9a9a9abottom left bar|r"},{id="bandage2",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Linen Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Garrote","Expose Armor"}},
  {kind="quest",chapter=4,lv="14–16",lo=14,hi=16,place="Northern Darkshore",title="The north: Buzzboxes, Blackwood camps and the tower",todo={"Follow the coast north. Kill |cffffd200threshers|r in the water for |cffffd2003 Thresher Eyes|r and hand them in at the |cffffd200Buzzbox 411|r machine on the northern beach. It gives |cffffd200Buzzbox 323|r: kill moonstalkers for it as you go.","|cffffd200The Blackwood Corrupted|r: fill the empty bowl at the Auberdine moonwell. Take a grain, a nut and a fruit sample from the three Blackwood furbolg camps, put the bowl by the bonfire at the last camp, and kill the demon that appears. Finish |cffffd200How Big a Threat?|r part 2 and |cffffd200Cleansing of the Infected|r around the same camps.","|cffffd200Cave Mushrooms|r: they grow in the cave behind |cffffd200Cliffspring Falls|r.","|cffffd200The Tower of Althalaxx|r: at the tower in the far north, talk to |cffffd200Balthule Shadowstrike|r and kill the Dark Strand cultists his quests ask for. The last Darkshore part sends you to Delgren the Purifier at Maestra's Post in Ashenvale."},done="you've handed in |cffffd200Buzzbox 411|r, |cffffd200How Big a Threat?|r part 2, |cffffd200Cleansing of the Infected|r, |cffffd200The Blackwood Corrupted|r and the first |cffffd200Tower of Althalaxx|r quests, and you're level 16.",stuck="Fight the Blackwood furbolgs at their camps until you are.",tip="Darkshore has a free bag: finish the |cffffd200Buzzbox|r chain (827, 411, 323, 525) and take |cffffd200Wizbang's Gunnysack|r as the reward. Buzzbox 525 wants scalps from the grizzled thistle bears.",talents={"Level 12–14: |cffffd200Coup de Grace|r, 3 times. Eviscerate hits harder.","Level 15–16: |cffffd200Precision|r, 2 times. You miss less often."},pins={{zone="Darkshore",x=51,y=35,label="Blackwood camps"},{zone="Darkshore",x=54.4,y=31.8,label="Cliffspring Falls (cave)"},{zone="Darkshore",x=55,y=25,label="Tower of Althalaxx"},{zone="Darkshore",x=38,y=29,label="Northern beach (threshers, Buzzbox 411)"}},quests={"threshers","Buzzbox 411","Buzzbox 323","The Blackwood Corrupted","How Big a Threat?","Cleansing of the Infected","Cave Mushrooms","Cliffspring Falls","The Tower of Althalaxx","Balthule Shadowstrike"}},
  {kind="train",chapter=4,lv="16",lo=16,hi=16,place="Darnassus (fly)",title="Level 16: Feint and Pick Lock",todo={"Learn |cffffd200Feint|r and |cffffd200Pick Lock|r, plus any new ranks.","Feint (|cff7fd4ffShift|r + |cff7fd4ff8|r) makes enemies less angry at you. In WoW Forever it works twice as well. Use it in dungeons so they keep attacking the |cffe2c6ff|Hwfw:33|htank|h|r.","Pick Lock opens locked boxes, but in WoW Forever it only works with |cffffd200Thieves' Tools|r in your bags. You get them from a quest in Stormwind at level 20. Keep any lockboxes you find until then.","Upgrade your supplies: |cffffd200Snapvine Watermelons|r from a food |cffe2c6ff|Hwfw:35|hvendor|h|r and |cffffd200Coarse Sharpening Stones|r from the |cffe2c6ff|Hwfw:2|hauction house|h|r."},done="Feint is on |cff7fd4ffShift|r + |cff7fd4ff8|r and Pick Lock is on your right bar.",bars={head="Action bar",rows={{id="feint",where="|cff7fd4ffShift|r + |cff7fd4ff8|r |cff9a9a9abottom left bar|r"},{id="picklock",where="Right bar, button |cffffd2006|r |cff9a9a9acounting from the top|r"},{id="food3",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Tel'Abim Banana"},{id="stone2",where="Right bar, button |cffffd2004|r |cff9a9a9acounting from the top|r",replaces="Rough Sharpening Stone"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 15–16: |cffffd200Precision|r, 2 times. You miss less often."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Feint","Pick Lock","Thieves' Tools","Snapvine Watermelons","Coarse Sharpening Stones"}},
  {kind="quest",chapter=4,lv="17–19",lo=17,hi=19,place="Southern Darkshore",title="The southern loop",todo={"|cffffd200Deep Ocean, Vast Sea|r (Gorbold Steelhand, Auberdine): swim out to the two sunken ships off the coast and loot the lockboxes in the wrecks. Watch your breath bar and the murlocs.","|cffffd200WANTED: Murkdeep!|r (the poster in Auberdine): at the murloc camp on the southern coast, kill the murlocs that come out until Murkdeep himself shows up.","Hand in |cffffd200Cave Mushrooms|r. It leads to |cffffd200Onu|r at the Grove of the Ancients: give him |cffffd200Grove of the Ancients|r too. Do his |cffffd200The Master's Glaive|r and |cffffd200The Twilight Camp|r, then |cffffd200Return to Onu|r.","Free |cffffd200Volcor|r in the south (the |cffffd200A Lost Master|r quests lead to him). Pick |cffffd200Escape Through |cffe2c6ff|Hwfw:30|hStealth|h|r|r: it's made for rogues. Stay in Stealth and walk him out.","|cffffd200The Sleeper Has Awakened|r: wake Kerlonian Evershade and walk him south to Maestra's Post in Ashenvale. When he falls asleep on the way, use the |cffffd200Horn of Awakening|r on him.","Skip |cffffd200The Absent Minded Prospector|r unless you have a group: one part is a group quest."},done="Murkdeep is dead, you've handed in |cffffd200Deep Ocean, Vast Sea|r and Onu's quests, Volcor is free, Kerlonian is following you, and you're level 19.",stuck="Fight the murlocs and bears in southern Darkshore until you are.",talents={"Level 17–19: |cffffd200Deflection|r, 3 times. You parry more attacks. Riposte needs all 3."},pins={{zone="Darkshore",x=36,y=76,label="Murkdeep's camp"},{zone="Darkshore",x=43.6,y=76.3,label="Onu (Grove of the Ancients)"},{zone="Darkshore",x=45,y=85.3,label="Volcor"},{zone="Darkshore",x=35.7,y=83.7,label="Prospector Remtravel (group quest)"}},quests={"Deep Ocean, Vast Sea","WANTED: Murkdeep!","Cave Mushrooms","Onu","Grove of the Ancients","The Master's Glaive","The Twilight Camp","Return to Onu","Volcor","A Lost Master","Escape Through Stealth","The Sleeper Has Awakened","Horn of Awakening","The Absent Minded Prospector"}},
  {kind="train",chapter=4,lv="18",lo=18,hi=18,place="Darnassus (fly)",title="Level 18: Ambush and Poised",todo={"Learn |cffffd200Ambush|r, |cffffd200Poised|r and new ranks of your attacks.","|cffffd200Poised|r works by itself: when you're out of combat with a full |cffe2c6ff|Hwfw:10|henergy|h|r bar, your next ability costs 10 less energy. So wait for full energy before you start a fight.","Ambush is a big hit from |cffe2c6ff|Hwfw:30|hStealth|h|r, but it needs a |cffffd200dagger|r. You're Combat, so leave it in the |cffe2c6ff|Hwfw:29|hspellbook|h|r unless you're still using the Blade of Cunning."},done="you've learned Ambush, Poised and the new ranks.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 17–19: |cffffd200Deflection|r, 3 times. You parry more attacks. Riposte needs all 3."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Ambush","Poised","dagger"}},
  {kind="travel",chapter=4,lv="19–20",lo=19,hi=20,place="Darkshore > Ashenvale",title="Into Ashenvale",todo={"Follow the road south out of Darkshore into |cffffd200Ashenvale|r, with Kerlonian behind you.","Stop at |cffffd200Maestra's Post|r. Hand in |cffffd200The Sleeper Has Awakened|r to Liladris Moonriver and your |cffffd200Tower of Althalaxx|r quest to |cffffd200Delgren the Purifier|r.","Follow the road east to |cffffd200Astranaar|r. Make the |cffe2c6ff|Hwfw:17|hinn|h|r your home and unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r."},done="you've handed in |cffffd200The Sleeper Has Awakened|r, Astranaar is your home and you've unlocked its |cffe2c6ff|Hwfw:13|hflight path|h|r.",talents={"Level 17–19: |cffffd200Deflection|r, 3 times. You parry more attacks. Riposte needs all 3.","Level 20: |cffffd200Riposte|r, once. A free counter-attack after you parry. Press it when it lights up."},pins={{zone="Darkshore",x=44,y=92,label="Road south to Ashenvale"},{zone="Ashenvale",x=26.2,y=38.7,label="Maestra's Post"},{zone="Ashenvale",x=36.5,y=49.5,label="Astranaar"}},quests={"Ashenvale","Maestra's Post","The Sleeper Has Awakened","Tower of Althalaxx","Delgren the Purifier","Astranaar"}},
  {kind="train",chapter=5,lv="20",lo=20,hi=20,place="Darnassus",title="Level 20: Rupture and Riposte",todo={"Learn |cffffd200Rupture|r and new ranks. Rupture is a bleeding |cffe2c6ff|Hwfw:12|hfinisher|h|r. Slice and Dice and Eviscerate are better while questing, so you can leave it in the |cffe2c6ff|Hwfw:29|hspellbook|h|r.","|cffe2c6ff|Hwfw:32|hTalent|h|r: put this level's point into |cffffd200Riposte|r (Combat tab). Open your |cffe2c6ff|Hwfw:29|hspellbook|h|r (|cff7fd4ffP|r) and put Riposte on key |cff7fd4ff-|r.","Rogues learn |cffffd200poisons|r from a quest in Stormwind: see the next two steps."},done="you've learned Rupture and the new ranks, and Riposte is on key |cff7fd4ff-|r.",tip="Riposte only lights up right after you parry an attack. When it lights up, press it.",bars={head="Action bar",rows={{id="riposte",where="Key |cff7fd4ff-|r |cff9a9a9amain bar|r"},{id="bandage3",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Heavy Linen Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 20: |cffffd200Riposte|r, once. A free counter-attack after you parry. Press it when it lights up."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Rupture","Riposte","poisons"}},
  {kind="quest",chapter=5,lv="20",lo=20,hi=20,place="Stormwind and Redridge",title="Thieves' Tools for Pick Lock",todo={"Go to |cffffd200Stormwind|r. From Auberdine, take the ship to Stormwind (new in WoW Forever). If you can't find it, take the boat to Menethil Harbor and travel through Ironforge and the Deeprun Tram. Unlock the Stormwind |cffe2c6ff|Hwfw:13|hflight path|h|r.","In |cffffd200Old Town|r, take |cffffd200Redridge Rendezvous|r from |cffffd200Renzik the Shiv|r.","Follow the road east through Elwynn Forest to |cffffd200Lakeshire|r in Redridge Mountains and unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r. Find |cffffd200Lucius|r on the pier and take |cffffd200Alther's Mill|r: he gives you the |cffffd200Thieves' Tools|r.","Follow the road east to |cffffd200Alther's Mill|r. Use Pick Lock on the |cffffd200Practice Lockboxes|r inside until your skill is 80. Then open |cffffd200Lucius's Lockbox|r and take it back to him."},done="|cffffd200Thieves' Tools|r are in your bags and your Pick Lock skill is at least 80.",tip="The poisons quest needs Pick Lock 75, so do this first. Your Pick Lock skill can go up to 5 times your level. Now open the lockboxes you've been saving.",talents={"Level 20: |cffffd200Riposte|r, once. A free counter-attack after you parry. Press it when it lights up."},pins={{zone="Darkshore",x=32.4,y=43.8,label="Auberdine docks"},{zone="Stormwind",x=75.8,y=59.8,label="Old Town: Renzik the Shiv and SI:7"},{zone="Stormwind",x=66.3,y=62.1,label="Flight master"},{zone="Redridge Mountains",x=30.6,y=59.4,label="Lakeshire (Lucius on the pier)"}},quests={"Stormwind","Old Town","Redridge Rendezvous","Renzik the Shiv","Lakeshire","Lucius","Alther's Mill","Thieves' Tools","Practice Lockboxes","Lucius's Lockbox"}},
  {kind="quest",chapter=5,lv="20",lo=20,hi=20,place="Stormwind and Westfall",title="Rogue quest: poisons",todo={"In |cffffd200Old Town|r, take |cffffd200Mathias and the Defias|r from |cffffd200Master Mathias Shaw|r at SI:7. Go to |cffffd200Sentinel Hill|r in Westfall, unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r, and make the |cffe2c6ff|Hwfw:17|hinn|h|r your home for now.","Find |cffffd200Agent Kearnen|r. She's in |cffe2c6ff|Hwfw:30|hStealth|h|r next to a big tree in the south-east corner of Westfall, just south of the road to Duskwood. She gives |cffffd200Klaven's Tower|r.","Use |cffffd200Pick Pocket|r on a |cffffd200Malformed Defias Drone|r to steal the |cffffd200Defias Tower Key|r. In |cffe2c6ff|Hwfw:30|hStealth|h|r, climb to the top of the nearby tower. |cffffd200Klaven Mortwake|r (level 23) waits there: |cffffd200Sap|r him, then open the small box beside him (Pick Lock 75) for |cffffd200Klaven Mortwake's Journal|r.","Use your |cffe2c6ff|Hwfw:15|hHearthstone|h|r while Klaven is still asleep. Fly to Stormwind and hand in to Mathias: you learn |cffffd200Poisons|r and how to make |cffffd200Thistle Tea|r.","Buy the ingredients from a |cffe2c6ff|Hwfw:21|hpoison|h|r |cffe2c6ff|Hwfw:35|hvendor|h|r, make |cffffd200Instant Poison|r in the Poisons window, and put poison on both weapons."},done="you've learned Poisons, made Instant |cffe2c6ff|Hwfw:21|hPoison|h|r, and both weapons have poison on them.",tip="Opening the box gives you a |cffe2c6ff|Hwfw:21|hpoison|h|r called |cffffd200Touch of Zanzil|r. To cure it, do Mathias's next quest, |cffffd200The Touch of Zanzil|r: Doc Mixilpixil in the cellar of the Stormwind Barracks wants Simple Wildflowers (from Bernard Gump), a Spool of Light Chartreuse Silk Thread (on the floor of the Finest Thread shop), a Bronze Tube and a Leaded Vial. How poisons work: open Poisons from your |cffe2c6ff|Hwfw:29|hspellbook|h|r (|cff7fd4ffP|r) and make them. Click the poison on your right bar, then click your weapon on the character window (|cff7fd4ffC|r). In WoW Forever, poisons have more charges and work together with sharpening stones.",bars={head="Action bar · when you next visit the trainer",rows={{id="poisons",where="Right bar, button |cffffd2003|r |cff9a9a9acounting from the top|r"},{id="ipois1",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r"},{id="opois1",where="Right bar, button |cffffd2002|r |cff9a9a9acounting from the top|r"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 20: |cffffd200Riposte|r, once. A free counter-attack after you parry. Press it when it lights up."},pins={{zone="Stormwind",x=75.8,y=59.8,label="Master Mathias Shaw (SI:7, Old Town)"},{zone="Westfall",x=56.4,y=47.5,label="Sentinel Hill (inn and flight path)"}},quests={"Old Town","Mathias and the Defias","Master Mathias Shaw","Sentinel Hill","Agent Kearnen","Klaven's Tower","Pick Pocket","Malformed Defias Drone","Defias Tower Key","Klaven Mortwake","Sap","Klaven Mortwake's Journal","Poisons","Thistle Tea","Instant Poison"}},
  {kind="quest",chapter=6,lv="20–24",lo=20,hi=24,place="Ashenvale",title="Quest Ashenvale",todo={"Take the ship back to Auberdine and fly to |cffffd200Astranaar|r. Make Astranaar your home again.","|cffffd200The Zoram Strand|r (Shindrell Swiftfire): 20 Wrathtail Heads from the naga on the far west coast.","|cffffd200Bathran's Hair|r: pick the plants at the ruins of Bathran's Haunt, north-west of town. Its follow-ups, |cffffd200Orendil's Cure|r and |cffffd200Elune's Tear|r, come next: your |cffe2c6ff|Hwfw:24|hquest log|h|r says where. After Elune's Tear, |cffffd200Pelturas Whitemoon|r gives |cffffd200The Ruins of Stardust|r: 5 Handfuls of Stardust from the sparkling bushes in the ruins south-west of town. Elementals can pop out.","|cffffd200Raene Wolfrunner|r at the |cffe2c6ff|Hwfw:17|hinn|h|r gives |cffffd200Raene's Cleansing|r (a long chain: follow it as far as you can) and |cffffd200An Aggressive Defense|r: kill Foulweald furbolgs at the camps south of the road east of town, before the river. Your |cffe2c6ff|Hwfw:24|hquest log|h|r lists how many of each.","Ashenvale has the Horde nearby. On |cffe2c6ff|Hwfw:23|hPvP|h|r servers, stay in |cffe2c6ff|Hwfw:30|hStealth|h|r while you travel."},done="you're level 24 and have handed in |cffffd200The Zoram Strand|r, |cffffd200Bathran's Hair|r, |cffffd200The Ruins of Stardust|r and |cffffd200An Aggressive Defense|r.",stuck="Fight the Foulweald furbolgs or the bears near Astranaar until you are.",talents={"Level 20: |cffffd200Riposte|r, once. A free counter-attack after you parry. Press it when it lights up.","Level 21: |cffffd200Precision|r, once more (3 of 3).","Level 22–23: |cffffd200Composure|r, 2 times. Poised saves you even more energy at the start of a fight.","Level 24: |cffffd200Endurance|r, once. Sprint and Evasion come back sooner."},pins={{zone="Ashenvale",x=36.5,y=49.5,label="Astranaar"},{zone="Ashenvale",x=14.5,y=26,label="Zoram Strand (naga)"},{zone="Ashenvale",x=30.5,y=31,label="Bathran's Haunt"},{zone="Ashenvale",x=33,y=67,label="Ruins of Stardust"},{zone="Ashenvale",x=20.3,y=42.4,label="Raene's Cleansing (first part)"}},quests={"Astranaar","The Zoram Strand","Bathran's Hair","Orendil's Cure","Elune's Tear","Pelturas Whitemoon","The Ruins of Stardust","Raene Wolfrunner","Raene's Cleansing","An Aggressive Defense"}},
  {kind="train",chapter=6,lv="22",lo=22,hi=22,place="Darnassus (fly)",title="Level 22: Vanish",todo={"Learn |cffffd200Vanish|r and |cffffd200Distract|r. Vanish needs |cffffd200Flash Powder|r: buy it from a |cffe2c6ff|Hwfw:21|hpoison|h|r |cffe2c6ff|Hwfw:35|hvendor|h|r.","Put Vanish on key |cff7fd4ff9|r. When a fight goes wrong, press it: you disappear into |cffe2c6ff|Hwfw:30|hStealth|h|r and the enemies forget you. Then walk away.","Distract makes enemies look the other way. You'll rarely need it, so leave it in the |cffe2c6ff|Hwfw:29|hspellbook|h|r."},done="Vanish is on key |cff7fd4ff9|r and you have Flash Powder in your bags.",bars={head="Action bar",rows={{id="vanish",where="Key |cff7fd4ff9|r |cff9a9a9amain bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 22–23: |cffffd200Composure|r, 2 times. Poised saves you even more energy at the start of a fight."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Vanish","Distract","Flash Powder"}},
  {kind="train",chapter=6,lv="24",lo=24,hi=24,place="Darnassus (fly)",title="Level 24: Shank",todo={"Learn |cffffd200Shank|r (new in WoW Forever), |cffffd200Detect Traps|r and |cffffd200Mind-numbing |cffe2c6ff|Hwfw:21|hPoison|h|r|r.","Put Shank on |cff7fd4ffShift|r + |cff7fd4ff-|r. Use it between your Sinister Strikes when it's ready."},done="Shank is on |cff7fd4ffShift|r + |cff7fd4ff-|r.",bars={head="Action bar",rows={{id="shank",where="|cff7fd4ffShift|r + |cff7fd4ff-|r |cff9a9a9abottom left bar|r"},{id="detecttraps",where="Right bar, button |cffffd2007|r |cff9a9a9acounting from the top|r"},{id="bandage4",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Wool Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 24: |cffffd200Endurance|r, once. Sprint and Evasion come back sooner."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Shank","Detect Traps","Mind-numbing Poison"}},
  {kind="dungeon",chapter=6,lv="22–27",lo=22,hi=27,place="Ashenvale",title="Dungeon: Blackfathom Deeps (optional)",todo={"A |cffe2c6ff|Hwfw:7|hdungeon|h|r is a private area for a group of 5 players. Blackfathom Deeps is in the far north-west of Ashenvale, on the coast.","Collect its quests first: |cffffd200Researching the Corruption|r (Gershala Nightwhisper, Auberdine), |cffffd200In Search of Thaelrid|r (Dawnwatcher Shaedlass, Darnassus), |cffffd200Twilight Falls|r (Argent Guard Manados, Darnassus) and |cffffd200Knowledge in the Deeps|r (Gerrig Bonegrip, Ironforge). Some more start inside.","Find a group: open the Looking For Group tool or ask in chat (\"LFG BFD\").","Inside, stay behind the |cffe2c6ff|Hwfw:33|htank|h|r (the player the enemies attack), hit the same enemy as the tank, and don't attack before the tank does."},done="your group has beaten the last boss, Aku'mai, or you've decided to skip it.",tip="Most |cffe2c6ff|Hwfw:7|hdungeon|h|r |cffe2c6ff|Hwfw:36|hXP|h|r in Forever comes from quests, not kills. Use Feint when an enemy starts attacking you instead of the |cffe2c6ff|Hwfw:33|htank|h|r.",talents={"Level 22–23: |cffffd200Composure|r, 2 times. Poised saves you even more energy at the start of a fight.","Level 24: |cffffd200Endurance|r, once. Sprint and Evasion come back sooner.","Level 25: |cffffd200Flawless Execution|r, once. Eviscerate costs 15 less energy.","Level 26–27: |cffffd200Weapon Expertise|r, 2 times. Enemies dodge and parry you less often."},pins={{zone="Ashenvale",x=14.5,y=14.2,label="Blackfathom Deeps entrance"},{zone="Ashenvale",x=36.5,y=49.5,label="Astranaar"}},quests={"Researching the Corruption","In Search of Thaelrid","Twilight Falls","Knowledge in the Deeps"}},
  {kind="talent",chapter=6,lv="25",lo=25,hi=25,place="Talents (N)",title="Level 25: Flawless Execution and Legacy",todo={"|cffe2c6ff|Hwfw:32|hTalent|h|r: |cffffd200Flawless Execution|r. Eviscerate now costs 15 less |cffe2c6ff|Hwfw:10|henergy|h|r.","Around now you get your first |cffffd200|cffe2c6ff|Hwfw:18|hLegacy|h|r|r point. Press |cff7fd4ffY|r and put it in |cffffd200Thrill of Adventure|r: every kill gives back some health."},done="your |cffe2c6ff|Hwfw:32|htalent|h|r point and your |cffe2c6ff|Hwfw:18|hLegacy|h|r point are spent.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 25: |cffffd200Flawless Execution|r, once. Eviscerate costs 15 less energy."},quests={"Flawless Execution","Legacy","Thrill of Adventure"}},
  {kind="train",chapter=6,lv="26",lo=26,hi=26,place="Darnassus (fly)",title="Level 26: Cheap Shot",todo={"Learn |cffffd200Cheap Shot|r and put it on |cff7fd4ffShift|r + |cff7fd4ff1|r.","Cheap Shot is an |cffe2c6ff|Hwfw:20|hopener|h|r: from |cffe2c6ff|Hwfw:30|hStealth|h|r it stuns the enemy for a few seconds and gives you 2 |cffe2c6ff|Hwfw:4|hcombo points|h|r.","Upgrade your supplies: |cffffd200Goldenbark Apples|r from a food |cffe2c6ff|Hwfw:35|hvendor|h|r and |cffffd200Heavy Sharpening Stones|r from the |cffe2c6ff|Hwfw:2|hauction house|h|r."},done="Cheap Shot is on |cff7fd4ffShift|r + |cff7fd4ff1|r.",tip="New fight: |cffe2c6ff|Hwfw:30|hStealth|h|r > walk up > Cheap Shot > Slice and Dice > Sinister Strike until 5 |cffe2c6ff|Hwfw:4|hcombo points|h|r > Eviscerate.",bars={head="Action bar",rows={{id="cheapshot",where="|cff7fd4ffShift|r + |cff7fd4ff1|r |cff9a9a9abottom left bar|r"},{id="food4",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Snapvine Watermelon"},{id="stone3",where="Right bar, button |cffffd2004|r |cff9a9a9acounting from the top|r",replaces="Coarse Sharpening Stone"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 26–27: |cffffd200Weapon Expertise|r, 2 times. Enemies dodge and parry you less often."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Cheap Shot","Goldenbark Apples","Heavy Sharpening Stones"}},
  {kind="quest",chapter=6,lv="24–28",lo=24,hi=28,place="Wetlands",title="The Wetlands",todo={"Take the boat from Auberdine to |cffffd200Menethil Harbor|r. Make the |cffe2c6ff|Hwfw:17|hinn|h|r your home and unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","Take every quest in town: |cffffd200Claws from the Deep|r (Karl Boran: kill 12 Bluegill murlocs and |cffffd200Gobbler|r, north of town, for his head), |cffffd200Young Crocolisk Skins|r (James Halloran: young crocolisks in the marsh) and |cffffd200Digging Through the Ooze|r (Sida: kill the black oozes at |cffffd200Ironbeard's Tomb|r, in the north past Dun Modr, until one drops |cffffd200Sida's Bag|r). Do the coast ones first.","Then move inland. |cffffd200The Greenwarden|r (First Mate Fitzsimmons) sends you to Rethiel the Greenwarden, who gives |cffffd200Tramping Paws|r (gnolls to the south-east) and more. From level 25, Harlo Barnaby's |cffffd200Fall of Dun Modr|r sends you to Longbraid the Grim at the dwarf ruins in the north. The Wetlands also got 20+ new quests in Forever: take any you find.","New |cffe2c6ff|Hwfw:7|hdungeon|h|r: |cffffd200Excavation Site|r, best at levels 26–29. Collect its quests from Caitlin Grassman in Menethil first."},done="you're level 28 and the Menethil Harbor quests are handed in.",stuck="Fight the murlocs or crocolisks along the Wetlands coast until you are.",tip="Pick Lock practice: once your skill is 110, the murloc camps north-east of Menethil Harbor have |cffffd200Battered Footlockers|r you can open.",talents={"Level 24: |cffffd200Endurance|r, once. Sprint and Evasion come back sooner.","Level 25: |cffffd200Flawless Execution|r, once. Eviscerate costs 15 less energy.","Level 26–27: |cffffd200Weapon Expertise|r, 2 times. Enemies dodge and parry you less often.","Level 28–29: |cffffd200Aggression|r, 2 times. Sinister Strike and Eviscerate hit harder."},pins={{zone="Darkshore",x=32.4,y=43.8,label="Auberdine docks: boat to Menethil"},{zone="Wetlands",x=10.5,y=60,label="Menethil Harbor"},{zone="Wetlands",x=34,y=42,label="Whelgar's Excavation Site"},{zone="Wetlands",x=56.4,y=40.4,label="The Greenwarden"},{zone="Wetlands",x=48,y=15,label="Dun Modr"},{zone="Wetlands",x=44,y=25,label="Ironbeard's Tomb"}},quests={"Menethil Harbor","Claws from the Deep","Gobbler","Young Crocolisk Skins","Digging Through the Ooze","Ironbeard's Tomb","Sida's Bag","The Greenwarden","Tramping Paws","Fall of Dun Modr","Excavation Site"}},
  {kind="train",chapter=6,lv="28",lo=28,hi=28,place="Ironforge, Stormwind or Darnassus",title="Level 28: stronger poison",todo={"Learn |cffffd200Instant |cffe2c6ff|Hwfw:21|hPoison|h|r II|r and new ranks. From Menethil Harbor, the closest trainers are in |cffffd200Ironforge|r (the Forlorn Cavern): fly there. Stormwind's are at SI:7 in Old Town.","Make Instant |cffe2c6ff|Hwfw:21|hPoison|h|r II in the Poisons window and put it on your main-hand weapon.","If the new |cffe2c6ff|Hwfw:21|hpoison|h|r is grey in the Poisons window, your Poisons skill is too low. Make a few of your old poisons first: each one raises the skill."},done="Instant |cffe2c6ff|Hwfw:21|hPoison|h|r II is on your main hand.",bars={head="Action bar",rows={{id="ipois2",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r",replaces="Instant Poison"},{id="bandage5",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Heavy Wool Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 28–29: |cffffd200Aggression|r, 2 times. Sinister Strike and Eviscerate hit harder."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}},quests={"Instant Poison II","Ironforge"}},
  {kind="quest",chapter=7,lv="28–30",lo=28,hi=30,place="Darkshire, Duskwood",title="Duskwood",todo={"Go to Stormwind (from Menethil Harbor: fly to Ironforge and take the Deeprun Tram), then follow the road south-east through Elwynn Forest into |cffffd200Duskwood|r, a dark forest. The town is |cffffd200Darkshire|r, on the east side. Make the |cffe2c6ff|Hwfw:17|hinn|h|r your home and unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","Take every quest in Darkshire. Start with |cffffd200Worgen in the Woods|r from Calor (wolf-men in Brightwood Grove, north-west of town) and |cffffd200The Night Watch|r from Commander Althea Ebonlock (skeletons in Raven Hill Cemetery, far west).","Many Duskwood quests lead into one story about |cffffd200Morbent Fel|r, a necromancer at the Tranquil Gardens Cemetery. Keep following it: it's one of the best stories in the game.","Skip quests marked |cffffd200|cffe2c6ff|Hwfw:8|hElite|h|r|r, like |cffffd200Mor'Ladim|r, unless you have a group. Move on at level 30."},done="you're level 30 and have handed in |cffffd200Worgen in the Woods|r and |cffffd200The Night Watch|r.",stuck="Fight the worgen in Brightwood Grove until you are.",tip="Worgen walk in pairs. They're humanoids, so Sap works on them: Sap one, kill the other, then fight the one that wakes up.",talents={"Level 28–29: |cffffd200Aggression|r, 2 times. Sinister Strike and Eviscerate hit harder.","Level 30: |cffffd200Blade Flurry|r, once. For 15 seconds you attack faster and every hit also hits a second enemy."},pins={{zone="Duskwood",x=73.5,y=46,label="Darkshire"},{zone="Duskwood",x=64,y=36,label="Brightwood Grove (worgen)"},{zone="Duskwood",x=20,y=45,label="Raven Hill Cemetery (skeletons)"},{zone="Duskwood",x=80,y=70,label="Tranquil Gardens Cemetery"}},quests={"Duskwood","Darkshire","Worgen in the Woods","The Night Watch","Morbent Fel","Elite","Mor'Ladim"}},
  {kind="train",chapter=7,lv="30",lo=30,hi=30,place="Stormwind trainer",title="Level 30: Kidney Shot and Deadly Poison",todo={"Fly to Stormwind and visit the rogue trainers at |cffffd200SI:7|r in Old Town. Learn |cffffd200Kidney Shot|r, |cffffd200Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r|r and |cffffd200Disarm Trap|r.","Kidney Shot (|cff7fd4ffShift|r + |cff7fd4ff4|r) is a |cffe2c6ff|Hwfw:12|hfinisher|h|r that stuns. Use it on enemies that cast spells, or when you need a break.","Put |cffffd200Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r|r on your off-hand weapon and keep Instant Poison on your main hand."},done="Kidney Shot is on |cff7fd4ffShift|r + |cff7fd4ff4|r and Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r is on your off hand.",tip="From now on you need a |cffe2c6ff|Hwfw:34|htrainer|h|r every 2 levels. Rogue trainers: SI:7 in Stormwind, the Forlorn Cavern in Ironforge, and the Cenarion Enclave in Darnassus. Use whichever is closest. Optional: your trainer also offers |cffffd200The Manor, Ravenholdt|r (needs Detect Traps). It sends you to Ravenholdt Manor in the Alterac Mountains; walk past the trapped chest in the cave.",bars={head="Action bar",rows={{id="kidney",where="|cff7fd4ffShift|r + |cff7fd4ff4|r |cff9a9a9abottom left bar|r"},{id="opois2",where="Right bar, button |cffffd2002|r |cff9a9a9acounting from the top|r",replaces="Crippling Poison"},{id="disarmtrap",where="Right bar, button |cffffd2008|r |cff9a9a9acounting from the top|r"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 30: |cffffd200Blade Flurry|r, once. For 15 seconds you attack faster and every hit also hits a second enemy."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers, Old Town)"}},quests={"SI:7","Kidney Shot","Deadly Poison","Disarm Trap"}},
  {kind="talent",chapter=7,lv="30",lo=30,hi=30,place="Talents (N)",title="Level 30: Blade Flurry",todo={"|cffe2c6ff|Hwfw:32|hTalent|h|r: |cffffd200Blade Flurry|r. Put it on |cff7fd4ffShift|r + |cff7fd4ff5|r.","When two enemies fight you, press it: for 15 seconds you attack faster and every hit also hits a second enemy."},done="Blade Flurry is on |cff7fd4ffShift|r + |cff7fd4ff5|r.",bars={head="Action bar",rows={{id="bladeflurry",where="|cff7fd4ffShift|r + |cff7fd4ff5|r |cff9a9a9abottom left bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 30: |cffffd200Blade Flurry|r, once. For 15 seconds you attack faster and every hit also hits a second enemy."},quests={"Blade Flurry"}},
  {kind="quest",chapter=7,lv="30–32",lo=30,hi=32,place="Arathi Highlands",title="Arathi Highlands",todo={"Fly to |cffffd200Menethil Harbor|r and ride north over the big bridge (Thandol Span) into |cffffd200Arathi Highlands|r, a wide open grassland.","In the middle is |cffffd200Refuge Pointe|r, the Alliance camp. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r and make it your home.","Take every quest. Captain Nials's |cffffd200Northfold Manor|r sends you to the Syndicate in the north-west. Sentinel Glynda Nal'Shea sends you after the Witherbark trolls in the south-east.","Stay out of |cffffd200Stromgarde Keep|r (west) unless you're in a group: it's full of |cffe2c6ff|Hwfw:8|helite|h|r enemies. |cffffd200Hammerfall|r (east) is a Horde town. Move on at level 32."},done="you're level 32 and have handed in |cffffd200Northfold Manor|r.",stuck="Fight the Syndicate around Northfold Manor until you are.",tip="The Syndicate are humanoids: Pick Pocket each one from |cffe2c6ff|Hwfw:30|hStealth|h|r before you attack. First Aid stuck at 150? |cffffd200Deneb Walker|r in Stromgarde sells the |cffffd200Expert First Aid|r book that lets you go higher.",talents={"Level 30: |cffffd200Blade Flurry|r, once. For 15 seconds you attack faster and every hit also hits a second enemy.","Level 31–34: |cffffd200Hack and Slash|r, 4 times. A bonus for whatever weapon you hold: swords, axes, maces, fists or daggers."},pins={{zone="Arathi Highlands",x=44,y=89,label="Thandol Span (from the Wetlands)"},{zone="Arathi Highlands",x=45.8,y=47.6,label="Refuge Pointe"},{zone="Arathi Highlands",x=32,y=28,label="Northfold Manor (Syndicate)"},{zone="Arathi Highlands",x=66,y=68,label="Witherbark Village (trolls)"},{zone="Arathi Highlands",x=25,y=30,label="Stromgarde Keep (elites)"},{zone="Arathi Highlands",x=73,y=33,label="Hammerfall (Horde town)"}},quests={"Menethil Harbor","Arathi Highlands","Refuge Pointe","Northfold Manor","Stromgarde Keep","Hammerfall"}},
  {kind="train",chapter=7,lv="32",lo=32,hi=32,place="Ironforge (fly from Refuge Pointe)",title="Level 32: new ranks",todo={"Fly to the nearest rogue |cffe2c6ff|Hwfw:34|htrainer|h|r (from Refuge Pointe, Ironforge is closest) and learn every new |cffe2c6ff|Hwfw:26|hrank|h|r. New ranks replace the old ones on your bars by themselves.","You can also learn |cffffd200Wound |cffe2c6ff|Hwfw:21|hPoison|h|r|r. You don't need it while questing: Instant Poison is better."},done="you've learned every new |cffe2c6ff|Hwfw:26|hrank|h|r your |cffe2c6ff|Hwfw:34|htrainer|h|r offers.",bars={head="Action bar",rows={{id="bandage6",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Silk Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 31–34: |cffffd200Hack and Slash|r, 4 times. A bonus for whatever weapon you hold: swords, axes, maces, fists or daggers."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}},quests={"Wound Poison"}},
  {kind="quest",chapter=7,lv="32",lo=32,hi=32,place="Southshore, Hillsbrad",title="Southshore",todo={"From Refuge Pointe, ride west through the gate in the huge wall (Thoradin's Wall) into Hillsbrad Foothills. Follow the road south to |cffffd200Southshore|r. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","Take the town's quests. |cffffd200Down the Coast|r from Lieutenant Farren Orinelle (murlocs on the beach) and |cffffd200Syndicate Assassins|r from Marshal Redpath (in the Alterac Mountains, north) are quick |cffe2c6ff|Hwfw:36|hXP|h|r.","Talk to |cffffd200Emissary Jacques|r to start the new |cffffd200City of Dalaran|r |cffe2c6ff|Hwfw:7|hdungeon|h|r (levels 28–35). Optional.","Southshore also has a boat to Auberdine. Move on at about level 33."},done="you're level 33 and have handed in |cffffd200Down the Coast|r and |cffffd200Syndicate Assassins|r.",stuck="Fight the murlocs on the beach south of Southshore until you are.",tip="From here on, on |cffe2c6ff|Hwfw:23|hPvP|h|r servers, Horde players can attack you. |cffe2c6ff|Hwfw:30|hStealth|h|r, Sprint and Vanish are your escape.",talents={"Level 31–34: |cffffd200Hack and Slash|r, 4 times. A bonus for whatever weapon you hold: swords, axes, maces, fists or daggers."},pins={{zone="Arathi Highlands",x=20,y=30,label="Gate in Thoradin's Wall (west)"},{zone="Hillsbrad Foothills",x=50,y=55,label="Southshore"},{zone="Hillsbrad Foothills",x=40,y=74,label="Murloc beach"}},quests={"Southshore","Down the Coast","Syndicate Assassins","Emissary Jacques","City of Dalaran"}},
  {kind="quest",chapter=8,lv="33–35",lo=33,hi=35,place="Stranglethorn Vale (north)",title="Stranglethorn: Rebel Camp and the hunters",todo={"Fly to |cffffd200Darkshire|r and follow the road south out of Duskwood into |cffffd200Stranglethorn Vale|r, a big jungle. Right at the |cffe2c6ff|Hwfw:37|hzone|h|r edge, turn west to the |cffffd200Rebel Camp|r.","Lieutenant Doren's quests at the Rebel Camp send you against the Kurzen soldiers at their compound, east of the camp.","Just south is |cffffd200Nesingwary's Expedition|r, a hunting camp. Take |cffffd200Tiger Mastery|r, |cffffd200Panther Mastery|r and |cffffd200Raptor Mastery|r: each sends you to hunt one kind of animal, and later parts send you after bigger ones.","Pages of |cffffd200The Green Hills of Stranglethorn|r drop from almost everything here. Keep them: when you have a full chapter, hand it to Barnil Stonepot at Nesingwary's camp for |cffe2c6ff|Hwfw:36|hXP|h|r."},done="you're level 35 and have handed in the first parts of |cffffd200Tiger Mastery|r, |cffffd200Panther Mastery|r and |cffffd200Raptor Mastery|r.",stuck="Fight the tigers and panthers around Nesingwary's camp until you are.",tip="Grom'gol, on the west coast, is a Horde camp. Stay away from it.",talents={"Level 31–34: |cffffd200Hack and Slash|r, 4 times. A bonus for whatever weapon you hold: swords, axes, maces, fists or daggers.","Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner."},pins={{zone="Stranglethorn Vale",x=38,y=3.5,label="Rebel Camp"},{zone="Stranglethorn Vale",x=35.6,y=10.6,label="Nesingwary's Expedition"},{zone="Stranglethorn Vale",x=44,y=10,label="Kurzen's Compound"},{zone="Stranglethorn Vale",x=32,y=28,label="Grom'gol (Horde camp)"}},quests={"Darkshire","Stranglethorn Vale","Rebel Camp","Nesingwary's Expedition","Tiger Mastery","Panther Mastery","Raptor Mastery","The Green Hills of Stranglethorn"}},
  {kind="train",chapter=8,lv="34",lo=34,hi=34,place="Nearest rogue trainer",title="Level 34: Blind",todo={"Learn |cffffd200Blind|r and put it on |cff7fd4ffShift|r + |cff7fd4ff0|r. It needs |cffffd200Blinding Powder|r: make it in the Poisons window. Each one needs a |cffffd200Fadeleaf|r herb: buy them at the |cffe2c6ff|Hwfw:2|hauction house|h|r.","Blind takes one enemy out of the fight for a while. Use it when a second enemy joins: Blind it, kill the first one, then deal with the blinded one."},done="Blind is on |cff7fd4ffShift|r + |cff7fd4ff0|r and you have Blinding Powder.",bars={head="Action bar",rows={{id="blind",where="|cff7fd4ffShift|r + |cff7fd4ff0|r |cff9a9a9abottom left bar|r"}},notes={"New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 31–34: |cffffd200Hack and Slash|r, 4 times. A bonus for whatever weapon you hold: swords, axes, maces, fists or daggers."},quests={"Blind","Blinding Powder","Fadeleaf"}},
  {kind="quest",chapter=8,lv="35–37",lo=35,hi=37,place="Booty Bay, Stranglethorn",title="Stranglethorn: Booty Bay",todo={"Follow the main road all the way south to |cffffd200Booty Bay|r, a goblin port built into a cliff. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r and make the |cffe2c6ff|Hwfw:17|hinn|h|r your home.","Booty Bay is neutral: Horde players use it too, and the goblin guards attack anyone who starts a fight in town.","Take |cffffd200Singing Blue Shards|r from Crank Fizzlebub (crystal-backed basilisks in the middle of the |cffe2c6ff|Hwfw:37|hzone|h|r) and the pirate quests that start with |cffffd200The Bloodsail Buccaneers|r from First Mate Crazz.","Keep doing the Nesingwary hunting quests as new parts open. Move on at level 37."},done="you're level 37 and have handed in |cffffd200Singing Blue Shards|r.",stuck="Fight the pirates or raptors along the coast near Booty Bay until you are.",tip="Upgrade your supplies: |cffffd200Solid Sharpening Stones|r (|cffe2c6ff|Hwfw:2|hauction house|h|r) and |cffffd200Moon Harvest Pumpkins|r (food vendors). Booty Bay also has a boat to Ratchet in Kalimdor.",bars={head="Action bar · when you next visit the trainer",rows={{id="stone4",where="Right bar, button |cffffd2004|r |cff9a9a9acounting from the top|r",replaces="Heavy Sharpening Stone"},{id="food5",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Goldenbark Apple"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner."},pins={{zone="Stranglethorn Vale",x=27,y=77,label="Booty Bay"},{zone="Stranglethorn Vale",x=38,y=3.5,label="Rebel Camp"},{zone="Stranglethorn Vale",x=35.6,y=10.6,label="Nesingwary's Expedition"}},quests={"Booty Bay","Singing Blue Shards","The Bloodsail Buccaneers"}},
  {kind="dungeon",chapter=8,lv="35–40",lo=35,hi=40,place="Tirisfal Glades",title="Dungeon: Scarlet Monastery (optional)",todo={"Four short |cffe2c6ff|Hwfw:7|hdungeon|h|r wings, run by crazed crusaders: |cffffd200|cffe2c6ff|Hwfw:14|hGraveyard|h|r|r (around level 30), |cffffd200Library|r (around 33), |cffffd200Armory|r (around 36) and |cffffd200Cathedral|r (around 38).","It's deep in Horde land, so don't walk there. Find a group with the Looking For Group tool and let the group summon you at the meeting stone outside.","Collect the Alliance quests first: |cffffd200Mythology of the Titans|r (Librarian Mae Paledust, Hall of Explorers in Ironforge) and |cffffd200In the Name of the Light|r (Raleigh the Devout, Southshore |cffe2c6ff|Hwfw:17|hinn|h|r).","Skip it if you'd rather keep questing."},done="your group has finished the wings you wanted, or you've decided to skip it.",tip="Inside, stay behind the |cffe2c6ff|Hwfw:33|htank|h|r and hit the same enemy. Feint when an enemy turns to you.",talents={"Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner.","Level 40: |cffffd200Adrenaline Rush|r, once. Energy fills twice as fast for 15 seconds. Your big button."},pins={{zone="Tirisfal Glades",x=83,y=33,label="Scarlet Monastery"}},quests={"Graveyard","Library","Armory","Cathedral","Mythology of the Titans","In the Name of the Light"}},
  {kind="train",chapter=8,lv="36",lo=36,hi=36,place="Nearest rogue trainer",title="Level 36: Instant Poison III",todo={"Fly to a rogue |cffe2c6ff|Hwfw:34|htrainer|h|r and learn new ranks and |cffffd200Instant |cffe2c6ff|Hwfw:21|hPoison|h|r III|r.","Make Instant |cffe2c6ff|Hwfw:21|hPoison|h|r III in the Poisons window and put it on your main-hand weapon.","Use your |cffe2c6ff|Hwfw:15|hHearthstone|h|r to get back to Booty Bay."},done="Instant |cffe2c6ff|Hwfw:21|hPoison|h|r III is on your main hand.",bars={head="Action bar",rows={{id="ipois3",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r",replaces="Instant Poison II"},{id="bandage7",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Heavy Silk Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}},quests={"Instant Poison III"}},
  {kind="travel",chapter=9,lv="37",lo=37,hi=37,place="Redridge > Riverglades",title="Travel to the Riverglades",todo={"Fly to |cffffd200Lakeshire|r in Redridge Mountains. No |cffe2c6ff|Hwfw:13|hflight path|h|r there yet? Fly to Darkshire and ride north-east into Redridge.","From Lakeshire, follow the road north toward the Burning Steppes. Near the edge of the map, a signpost at a crossroads points to the Riverglades: take the right-hand path into the hills.","Follow that road south to |cffffd200Farholde Keep|r, the Alliance town in the Riverglades (a new |cffe2c6ff|Hwfw:37|hzone|h|r in WoW Forever).","Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r (Gretchen Mayberry) and make the |cffe2c6ff|Hwfw:17|hinn|h|r your home. From now on you can fly straight between Farholde Keep and Lakeshire."},done="Farholde Keep is your home (hover over your |cffe2c6ff|Hwfw:15|hHearthstone|h|r to check) and you've unlocked its |cffe2c6ff|Hwfw:13|hflight path|h|r.",talents={"Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner."},pins={{zone="Redridge Mountains",x=30.6,y=59.4,label="Lakeshire flight path"}},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."},quests={"Lakeshire","Farholde Keep"}},
  {kind="quest",chapter=9,lv="37–40",lo=37,hi=40,place="Farholde Keep, Riverglades",title="Riverglades: around Farholde Keep",todo={"Take every quest in Farholde Keep. Many come from |cffffd200Demar Brant|r, the knight in charge, and the people around him. There are over 70 Alliance quests in this |cffe2c6ff|Hwfw:37|hzone|h|r.","Riverglades quests come in waves: when you finish a batch, new ones usually appear back in Farholde Keep. Check the town after every few turn-ins.","Start with the farms and lookouts close to the keep. The enemies get tougher the further north you go.","The Horde quests here too (their town is Rog'mar). On |cffe2c6ff|Hwfw:23|hPvP|h|r servers, keep your escape buttons ready. Move on at level 40."},done="you're level 40.",stuck="Fight the enemies near your current quests in the south of the |cffe2c6ff|Hwfw:37|hzone|h|r until you are.",tip="There's no Riverglades map on this site yet. Use your in-game map (|cff7fd4ffM|r): Farholde Keep is in the south of the |cffe2c6ff|Hwfw:37|hzone|h|r.",talents={"Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner.","Level 40: |cffffd200Adrenaline Rush|r, once. Energy fills twice as fast for 15 seconds. Your big button."},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."},quests={"Demar Brant"}},
  {kind="train",chapter=9,lv="38",lo=38,hi=38,place="Nearest rogue trainer",title="Level 38: Deadly Poison II",todo={"Fly to a rogue |cffe2c6ff|Hwfw:34|htrainer|h|r (Lakeshire flies to Stormwind) and learn new ranks and |cffffd200Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r II|r.","Make it and put it on your off-hand weapon.","Start saving gold now: your mount costs a lot at level 40."},done="Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r II is on your off hand.",bars={head="Action bar",rows={{id="opois3",where="Right bar, button |cffffd2002|r |cff9a9a9acounting from the top|r",replaces="Deadly Poison"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 35–39: |cffffd200Flash of Steel|r, 5 times. Shank gives you more energy and is ready sooner."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}},quests={"Deadly Poison II"}},
  {kind="train",chapter=9,lv="40",lo=40,hi=40,place="Trainer + Darnassus",title="Level 40: your mount!",todo={"In Darnassus, learn riding from |cffffd200Jartsam|r and buy a |cffffd200nightsaber|r from |cffffd200Lelanai|r next to him. Darnassus reputation makes it cheaper. Right-click the mount item to learn it, then drag it from your |cffe2c6ff|Hwfw:29|hspellbook|h|r to the right bar.","Learn |cffffd200Safe Fall|r and new ranks at the |cffe2c6ff|Hwfw:34|htrainer|h|r.","|cffe2c6ff|Hwfw:32|hTalent|h|r: |cffffd200Adrenaline Rush|r. Put it on |cff7fd4ffShift|r + |cff7fd4ff6|r. Your |cffe2c6ff|Hwfw:10|henergy|h|r fills twice as fast for a short time. Use it for hard fights."},done="you're riding your nightsaber and Adrenaline Rush is on |cff7fd4ffShift|r + |cff7fd4ff6|r.",tip="At level 40 you can also unlock a second |cffe2c6ff|Hwfw:32|htalent|h|r setup (Dual Specialization) at a |cffe2c6ff|Hwfw:34|htrainer|h|r in a big city.",bars={head="Action bar",rows={{id="mount",where="Right bar, button |cffffd20011|r |cff9a9a9acounting from the top|r"},{id="adrenaline",where="|cff7fd4ffShift|r + |cff7fd4ff6|r |cff9a9a9abottom left bar|r"},{id="bandage8",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Mageweave Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 40: |cffffd200Adrenaline Rush|r, once. Energy fills twice as fast for 15 seconds. Your big button."},pins={{zone="Darnassus",x=38.5,y=16.7,label="Lelanai (nightsaber vendor)"}},quests={"Jartsam","nightsaber","Lelanai","Safe Fall","Adrenaline Rush"}},
  {kind="quest",chapter=9,lv="40–43",lo=40,hi=43,place="Riverglades (north)",title="Riverglades: Sunnyglade and the north",todo={"Fly back to Farholde Keep. Demar Brant's |cffffd200Saving Sunnyglade|r sends you north to the village of |cffffd200Sunnyglade|r.","Keep turning in and picking up: the later quests send you further north, toward |cffffd200Twilight's Shroud|r.","Pick up the quests for the |cffe2c6ff|Hwfw:7|hdungeon|h|r |cffffd200Krol'dok Stronghold|r (next step) as they appear.","|cffffd200Powderfuse Port|r, a neutral goblin port on the east coast, has a bank, an |cffe2c6ff|Hwfw:2|hauction house|h|r and the boat to Tanaris. Move on at about level 43."},done="you're level 43 and have handed in |cffffd200Saving Sunnyglade|r.",stuck="Fight the enemies around Sunnyglade until you are.",talents={"Level 40: |cffffd200Adrenaline Rush|r, once. Energy fills twice as fast for 15 seconds. Your big button.","Level 41: |cffffd200Hack and Slash|r, once more (5 of 5).","Level 42: |cffffd200Aggression|r, once more (3 of 3).","Level 43–44: |cffffd200Dual Wield Specialization|r, 2 times. Your off-hand weapon hits harder."},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."},quests={"Saving Sunnyglade","Sunnyglade","Twilight's Shroud","Krol'dok Stronghold","Powderfuse Port"}},
  {kind="train",chapter=9,lv="42",lo=42,hi=42,place="Stormwind (fly from Farholde Keep)",title="Level 42: new ranks",todo={"Fly from Farholde Keep to Lakeshire, then on to Stormwind. Learn every new |cffe2c6ff|Hwfw:26|hrank|h|r at SI:7.","Hearth back to Farholde Keep and carry on."},done="you've learned every new |cffe2c6ff|Hwfw:26|hrank|h|r your |cffe2c6ff|Hwfw:34|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 42: |cffffd200Aggression|r, once more (3 of 3)."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}}},
  {kind="dungeon",chapter=9,lv="41–45",lo=41,hi=45,place="Riverglades",title="Dungeon: Krol'dok Stronghold (optional)",todo={"A new 5-player |cffe2c6ff|Hwfw:7|hdungeon|h|r for levels 40–45, with six bosses. The entrance is in the hills north of Sunnyglade (with TomTom: |cff7fd4ff/way 37.5 37.5|r).","Its quests are a chain of about ten that starts in Farholde Keep. Do the parts you can do alone first.","Find a group with the Looking For Group tool or ask in chat (\"LFG Krol'dok\")."},done="your group has beaten the last boss, or you've decided to skip it.",tip="Most |cffe2c6ff|Hwfw:7|hdungeon|h|r |cffe2c6ff|Hwfw:36|hXP|h|r in Forever comes from quests, so collect them before you go in.",talents={"Level 41: |cffffd200Hack and Slash|r, once more (5 of 5).","Level 42: |cffffd200Aggression|r, once more (3 of 3).","Level 43–44: |cffffd200Dual Wield Specialization|r, 2 times. Your off-hand weapon hits harder.","Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit."},mapNotes={"Riverglades is new in WoW: Forever, so there's no map of it here yet. Follow the directions above."}},
  {kind="travel",chapter=10,lv="43",lo=43,hi=43,place="Riverglades > Tanaris",title="Travel to Tanaris",todo={"Ride to |cffffd200Powderfuse Port|r on the Riverglades' east coast and take the boat to |cffffd200Steamwheedle Port|r in Tanaris, a desert in Kalimdor.","Follow the road west to |cffffd200Gadgetzan|r, the goblin town. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r and make the |cffe2c6ff|Hwfw:17|hinn|h|r your home.","Gadgetzan is neutral: its guards attack anyone who starts a fight in town."},done="Gadgetzan is your home and you've unlocked its |cffe2c6ff|Hwfw:13|hflight path|h|r.",talents={"Level 43–44: |cffffd200Dual Wield Specialization|r, 2 times. Your off-hand weapon hits harder."},pins={{zone="Tanaris",x=67.5,y=23,label="Steamwheedle Port (boat)"},{zone="Tanaris",x=51,y=28,label="Gadgetzan"}},quests={"Powderfuse Port","Steamwheedle Port","Gadgetzan"}},
  {kind="quest",chapter=10,lv="43–46",lo=43,hi=46,place="Gadgetzan, Tanaris",title="Tanaris",todo={"Take every quest in Gadgetzan. |cffffd200Wastewander Justice|r and |cffffd200Water Pouch Bounty|r send you to the bandit camps east of town.","|cffffd200Noxious Lair Investigation|r from Alchemist Pestlezugg: giant insects at the Noxious Lair, south-west of town.","Steamwheedle Port has pirate quests (|cffffd200Southsea Shakedown|r, |cffffd200Pirate Hats Ahoy!|r) for the pirates at |cffffd200Lost Rigger Cove|r on the east coast.","Gadgetzan also has quests for |cffffd200Zul'Farrak|r, the |cffe2c6ff|Hwfw:7|hdungeon|h|r in the north-west. Move on at about level 46."},done="you're level 46 and have handed in |cffffd200Wastewander Justice|r and |cffffd200Water Pouch Bounty|r.",stuck="Fight the Wastewander bandits east of Gadgetzan until you are.",tip="Bandits and pirates are humanoids: Pick Pocket them for extra gold. Bandits run away at low health, so finish them with Kidney Shot or Throw.",talents={"Level 43–44: |cffffd200Dual Wield Specialization|r, 2 times. Your off-hand weapon hits harder.","Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit."},pins={{zone="Tanaris",x=51,y=28,label="Gadgetzan"},{zone="Tanaris",x=63,y=30,label="Wastewander bandit camps"},{zone="Tanaris",x=35,y=45,label="Noxious Lair (giant insects)"},{zone="Tanaris",x=72,y=46,label="Lost Rigger Cove (pirates)"},{zone="Tanaris",x=39,y=20,label="Zul'Farrak"}},quests={"Wastewander Justice","Water Pouch Bounty","Noxious Lair Investigation","Southsea Shakedown","Pirate Hats Ahoy!","Lost Rigger Cove","Zul'Farrak"}},
  {kind="train",chapter=10,lv="44",lo=44,hi=44,place="Nearest rogue trainer",title="Level 44: Instant Poison IV",todo={"Learn new ranks and |cffffd200Instant |cffe2c6ff|Hwfw:21|hPoison|h|r IV|r. While you're in Kalimdor, Darnassus is the closest |cffe2c6ff|Hwfw:34|htrainer|h|r (fly to Rut'theran Village, then take the portal up).","Make it and put it on your main-hand weapon. Hearth back to Gadgetzan."},done="Instant |cffe2c6ff|Hwfw:21|hPoison|h|r IV is on your main hand.",bars={head="Action bar",rows={{id="ipois4",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r",replaces="Instant Poison III"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 43–44: |cffffd200Dual Wield Specialization|r, 2 times. Your off-hand weapon hits harder."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"},{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}},quests={"Instant Poison IV"}},
  {kind="dungeon",chapter=10,lv="44–48",lo=44,hi=48,place="Tanaris",title="Dungeon: Zul'Farrak (optional)",todo={"A troll city in the north-west of Tanaris, for levels 44–48. Lots of quests from Gadgetzan.","Good ones: |cffffd200Divino-matic Rod|r (Chief Engineer Bilgewhizzle) and |cffffd200Troll Temper|r (Trenton Lighthammer).","Find a group with the Looking For Group tool or ask in chat (\"LFG ZF\")."},done="your group has finished, or you've decided to skip it.",talents={"Level 43–44: |cffffd200Dual Wield Specialization|r, 2 times. Your off-hand weapon hits harder.","Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit.","Level 47–49: |cffffd200Malice|r, 3 times. More critical hits."},pins={{zone="Tanaris",x=39,y=20,label="Zul'Farrak"},{zone="Tanaris",x=51,y=28,label="Gadgetzan"}},quests={"Divino-matic Rod","Troll Temper"}},
  {kind="talent",chapter=10,lv="45",lo=45,hi=45,place="Talents (N)",title="Level 45: Assassination talents",todo={"Combat is done: from now on your |cffe2c6ff|Hwfw:32|htalent|h|r points go into the |cffffd200Assassination|r tab, starting with |cffffd200Remorseless Attacks|r. After a kill, your next Sinister Strike is much more likely to crit.","The Talents tab shows the order to the end. At 60 you've spent all 51 points."},done="your new point is in |cffffd200Remorseless Attacks|r.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit."},quests={"Assassination","Remorseless Attacks"}},
  {kind="travel",chapter=10,lv="46",lo=46,hi=46,place="Tanaris > Feralas",title="Travel to Feralas",todo={"From Gadgetzan, ride north into |cffffd200Thousand Needles|r. Cross the white salt flats and keep heading west along the canyon road. (Freewind Post, up on the cliffs, is Horde.)","The road leads to |cffffd200Thalanaar|r, a night elf outpost at the east edge of Feralas. Unlock its |cffe2c6ff|Hwfw:13|hflight path|h|r.","Ride west through the jungle to the coast. |cffffd200Feathermoon Stronghold|r is on an island: take the ferry from the small dock on the shore.","Unlock the Feathermoon |cffe2c6ff|Hwfw:13|hflight path|h|r and make the |cffe2c6ff|Hwfw:17|hinn|h|r your home."},done="Feathermoon Stronghold is your home and you've unlocked the Thalanaar and Feathermoon flight paths.",talents={"Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit."},pins={{zone="Thousand Needles",x=78,y=77,label="Shimmering Flats"},{zone="Feralas",x=89.5,y=46,label="Thalanaar"},{zone="Feralas",x=43.5,y=43,label="Ferry dock to Feathermoon"},{zone="Feralas",x=30.5,y=43.5,label="Feathermoon Stronghold"}},quests={"Thousand Needles","Thalanaar","Feathermoon Stronghold"}},
  {kind="train",chapter=10,lv="46",lo=46,hi=46,place="Nearest rogue trainer",title="Level 46: Deadly Poison III",todo={"Feathermoon flies to Rut'theran Village, next to Darnassus. Learn new ranks and |cffffd200Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r III|r.","Upgrade your supplies: |cffffd200Dense Sharpening Stones|r (|cffe2c6ff|Hwfw:2|hauction house|h|r) and |cffffd200Deep Fried Plantains|r (food vendors)."},done="Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r III is on your off hand.",bars={head="Action bar",rows={{id="opois4",where="Right bar, button |cffffd2002|r |cff9a9a9acounting from the top|r",replaces="Deadly Poison II"},{id="stone5",where="Right bar, button |cffffd2004|r |cff9a9a9acounting from the top|r",replaces="Solid Sharpening Stone"},{id="food6",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Moon Harvest Pumpkin"},{id="bandage9",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Heavy Mageweave Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Deadly Poison III","Dense Sharpening Stones","Deep Fried Plantains"}},
  {kind="quest",chapter=10,lv="46–48",lo=46,hi=48,place="Feathermoon, Feralas",title="Feralas",todo={"Take every quest in Feathermoon Stronghold, like |cffffd200The Mark of Quality|r from Pratt McGrubben (yeti hides) and the |cffffd200Rise of the Silithid|r chain.","Near the ferry dock, |cffffd200Zorbin Fandazzle|r gives |cffffd200Zapped Giants|r: use his gadget on the giants that walk along the coast.","|cffffd200Dire Maul|r, the ruined city in the middle of Feralas, is a |cffe2c6ff|Hwfw:7|hdungeon|h|r for levels 55–60. Come back much later.","Move on at about level 48."},done="you're level 48 and have handed in |cffffd200Zapped Giants|r and |cffffd200The Mark of Quality|r.",stuck="Fight the yetis in the hills or the giants on the coast until you are.",talents={"Level 45–46: |cffffd200Remorseless Attacks (Assassination tab)|r, 2 times. Switch to the Assassination tab now. After a kill, your next Sinister Strike is more likely to crit.","Level 47–49: |cffffd200Malice|r, 3 times. More critical hits."},pins={{zone="Feralas",x=30.5,y=43.5,label="Feathermoon Stronghold"},{zone="Feralas",x=43.5,y=43,label="Ferry dock"},{zone="Feralas",x=59,y=44,label="Dire Maul (for later)"}},quests={"The Mark of Quality","Rise of the Silithid","Zorbin Fandazzle","Zapped Giants","Dire Maul"}},
  {kind="train",chapter=10,lv="48",lo=48,hi=48,place="Darnassus (fly from Feathermoon)",title="Level 48: new ranks",todo={"Fly from Feathermoon to Rut'theran Village, take the portal up to Darnassus and learn every new |cffe2c6ff|Hwfw:26|hrank|h|r.","You're now in Rut'theran, close to the boat at Auberdine: go straight on to the Hinterlands (next step)."},done="you've learned every new |cffe2c6ff|Hwfw:26|hrank|h|r your |cffe2c6ff|Hwfw:34|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 47–49: |cffffd200Malice|r, 3 times. More critical hits."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}}},
  {kind="quest",chapter=10,lv="47–50",lo=47,hi=50,place="Aerie Peak, Hinterlands",title="The Hinterlands",todo={"Back to the Eastern Kingdoms: fly to Auberdine and take the boat to |cffffd200Southshore|r (or the boat to Menethil Harbor, then fly to Southshore). From Southshore, ride north-east into |cffffd200The Hinterlands|r. |cffffd200Aerie Peak|r, the Wildhammer dwarf town, is right at the entrance.","Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r and make the |cffe2c6ff|Hwfw:17|hinn|h|r your home.","Take every quest: |cffffd200Skulk Rock Clean-up|r (oozes at Skulk Rock), |cffffd200Troll Necklace Bounty|r (necklaces from any Witherbark troll) and Gryphon Master Talonaxe's chain, starting with |cffffd200Witherbark Cages|r.","Run out of quests? |cffffd200Searing Gorge|r (town: Thorium Point) is another |cffe2c6ff|Hwfw:37|hzone|h|r for this level. Move on at level 50."},done="you're level 50 and have handed in |cffffd200Skulk Rock Clean-up|r and |cffffd200Troll Necklace Bounty|r.",stuck="Fight Witherbark trolls (their necklaces count for the bounty) until you are.",tip="WoW Forever adds a new |cffe2c6ff|Hwfw:7|hdungeon|h|r for these levels: |cffffd200Alcaz Prison|r (about 48–53). Look for it in the Looking For Group tool.",talents={"Level 47–49: |cffffd200Malice|r, 3 times. More critical hits.","Level 50–52: |cffffd200Ruthlessness|r, 3 times. Finishers sometimes give a free combo point."},pins={{zone="The Hinterlands",x=14,y=46,label="Aerie Peak"},{zone="The Hinterlands",x=55,y=42,label="Skulk Rock (oozes)"},{zone="The Hinterlands",x=63,y=73,label="Jintha'Alor (trolls)"}},quests={"Southshore","The Hinterlands","Aerie Peak","Skulk Rock Clean-up","Troll Necklace Bounty","Witherbark Cages","Searing Gorge"}},
  {kind="quest",chapter=11,lv="49–52",lo=49,hi=52,place="Marshal's Refuge, Un'Goro",title="Un'Goro Crater",todo={"Fly to Gadgetzan (from the Hinterlands: fly to Menethil Harbor, take the boat to Auberdine, then fly to Gadgetzan) and ride west out of Tanaris. The road goes down a long ramp into |cffffd200Un'Goro Crater|r, a jungle full of dinosaurs.","Follow the crater's edge north to |cffffd200Marshal's Refuge|r, a camp under the northern cliffs. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","Take every quest. |cffffd200Crystals of Power|r from J.D. Collie: pick up the coloured crystals that lie on the ground all over the crater (your |cffe2c6ff|Hwfw:24|hquest log|h|r says which colours and how many). Karna Remtravel's |cffffd200Chasing A-Me 01|r sends you to walk a lost robot home.","Watch out for |cffffd200Devilsaurs|r: huge dinosaurs that walk around and hit very hard. Stay out of their way. Move on at level 52."},done="you're level 52 and have handed in |cffffd200Crystals of Power|r and |cffffd200Chasing A-Me 01|r.",stuck="Fight the raptors and stegodons near Marshal's Refuge until you are.",tip="Devilsaurs can't see you in |cffe2c6ff|Hwfw:30|hStealth|h|r. If one comes your way, Stealth and step aside.",talents={"Level 47–49: |cffffd200Malice|r, 3 times. More critical hits.","Level 50–52: |cffffd200Ruthlessness|r, 3 times. Finishers sometimes give a free combo point."},pins={{zone="Un'Goro Crater",x=43.5,y=8.5,label="Marshal's Refuge"},{zone="Un'Goro Crater",x=50,y=48,label="Fire Plume Ridge (volcano)"},{zone="Un'Goro Crater",x=70,y=75,label="Entrance from Tanaris"}},quests={"Un'Goro Crater","Marshal's Refuge","Crystals of Power","Chasing A-Me 01","Devilsaurs"}},
  {kind="train",chapter=11,lv="50",lo=50,hi=50,place="Darnassus (fly from Marshal's Refuge)",title="Level 50: new ranks",todo={"Fly to Rut'theran Village, take the portal up to Darnassus and learn every new |cffe2c6ff|Hwfw:26|hrank|h|r.","|cffe2c6ff|Hwfw:32|hTalent|h|r: |cffffd200Ruthlessness|r (Assassination tab).","Optional: your |cffe2c6ff|Hwfw:34|htrainer|h|r offers |cffffd200A Simple Request|r, a long rogue chain (Ravenholdt Manor, Azshara, then Sunken Temple with a group). Its rewards are very good, but it takes time."},done="you've learned every new |cffe2c6ff|Hwfw:26|hrank|h|r your |cffe2c6ff|Hwfw:34|htrainer|h|r offers and your |cffe2c6ff|Hwfw:32|htalent|h|r point is spent.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 50–52: |cffffd200Ruthlessness|r, 3 times. Finishers sometimes give a free combo point."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Ruthlessness","A Simple Request"}},
  {kind="train",chapter=11,lv="52",lo=52,hi=52,place="Nearest rogue trainer",title="Level 52: Instant Poison V",todo={"Learn new ranks and |cffffd200Instant |cffe2c6ff|Hwfw:21|hPoison|h|r V|r. Put it on your main-hand weapon."},done="Instant |cffe2c6ff|Hwfw:21|hPoison|h|r V is on your main hand.",bars={head="Action bar",rows={{id="ipois5",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r",replaces="Instant Poison IV"},{id="bandage10",where="|cff7fd4ffAlt|r + |cff7fd4ff1|r |cff9a9a9abottom right bar|r",replaces="Runecloth Bandage"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 50–52: |cffffd200Ruthlessness|r, 3 times. Finishers sometimes give a free combo point."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Instant Poison V"}},
  {kind="quest",chapter=11,lv="52–54",lo=52,hi=54,place="Felwood",title="Felwood",todo={"Fly to |cffffd200Astranaar|r in Ashenvale and follow the road north into |cffffd200Felwood|r, a forest poisoned by demons.","In the south, stop at the |cffffd200Emerald Sanctuary|r camp. |cffffd200Forces of Jaedenar|r from Greta Mosshoof sends you after the demon worshippers at Jaedenar, west of the road.","Follow the road north to |cffffd200Talonbranch Glade|r. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r and take its quests.","Near the north end, Nafien gives |cffffd200Deadwood of the North|r: killing the Deadwood furbolgs makes the Timbermaw furbolgs like you, so they let you walk through their tunnel to Winterspring later. Move on at level 54."},done="you're level 54 and have handed in |cffffd200Forces of Jaedenar|r and |cffffd200Deadwood of the North|r.",stuck="Fight Deadwood furbolgs in northern Felwood until you are. It also makes the Timbermaw like you.",talents={"Level 50–52: |cffffd200Ruthlessness|r, 3 times. Finishers sometimes give a free combo point.","Level 53–54: |cffffd200Malice|r, 2 more times (5 of 5)."},pins={{zone="Felwood",x=51,y=82,label="Emerald Sanctuary"},{zone="Felwood",x=37,y=60,label="Jaedenar (Shadow Council)"},{zone="Felwood",x=62.5,y=24.5,label="Talonbranch Glade"},{zone="Felwood",x=64.5,y=8,label="Timbermaw Hold (tunnel to Winterspring)"}},quests={"Astranaar","Felwood","Emerald Sanctuary","Forces of Jaedenar","Talonbranch Glade","Deadwood of the North"}},
  {kind="train",chapter=11,lv="54",lo=54,hi=54,place="Nearest rogue trainer",title="Level 54: Deadly Poison IV",todo={"Learn new ranks and |cffffd200Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r IV|r. Put it on your off-hand weapon."},done="Deadly |cffe2c6ff|Hwfw:21|hPoison|h|r IV is on your off hand.",bars={head="Action bar",rows={{id="opois5",where="Right bar, button |cffffd2002|r |cff9a9a9acounting from the top|r",replaces="Deadly Poison III"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 53–54: |cffffd200Malice|r, 2 more times (5 of 5)."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Deadly Poison IV"}},
  {kind="quest",chapter=11,lv="54–56",lo=54,hi=56,place="Morgan's Vigil, Burning Steppes",title="Burning Steppes",todo={"Fly to Lakeshire and ride north into |cffffd200Burning Steppes|r, a scorched land of orcs and dragons. |cffffd200Morgan's Vigil|r, the Alliance camp, is just over the border. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","Take every quest. |cffffd200Dragonkin Menace|r from Helendis Riverhorn (black dragonkin in the north) starts a very long chain that matters much later at 60.","The Blackrock orcs all over the |cffe2c6ff|Hwfw:37|hzone|h|r are targets for several quests.","|cffffd200Blackrock Depths|r, a huge |cffe2c6ff|Hwfw:7|hdungeon|h|r inside Blackrock Mountain (west), is great from 52 to 60. Go with a group. Move on at level 56."},done="you're level 56 and have handed in |cffffd200Dragonkin Menace|r.",stuck="Fight the Blackrock orcs around the |cffe2c6ff|Hwfw:37|hzone|h|r until you are.",tip="WoW Forever adds new dungeons for these levels too: |cffffd200Blackmaw Hold|r (55–60) and |cffffd200Shaper's Terrace|r (58–60). Look for them in the Looking For Group tool.",talents={"Level 53–54: |cffffd200Malice|r, 2 more times (5 of 5).","Level 55: |cffffd200Blood Splatter|r, once. Rupture and Garrote last longer.","Level 56–57: |cffffd200Improved Slice and Dice|r, 2 times. Slice and Dice lasts longer."},pins={{zone="Burning Steppes",x=84,y=68,label="Morgan's Vigil"},{zone="Burning Steppes",x=65,y=24,label="Flame Crest (black dragons)"},{zone="Burning Steppes",x=28,y=36,label="Blackrock Mountain"}},quests={"Burning Steppes","Morgan's Vigil","Dragonkin Menace","Blackrock Depths"}},
  {kind="quest",chapter=11,lv="55–57",lo=55,hi=57,place="Chillwind Camp, Western Plaguelands",title="Western Plaguelands",todo={"Fly to Southshore and ride north through the Alterac Mountains into |cffffd200Western Plaguelands|r. |cffffd200Chillwind Camp|r is just inside, in the south. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","|cffffd200The Scourge Cauldrons|r chain: undead lords guard four cauldrons that |cffe2c6ff|Hwfw:21|hpoison|h|r the land, at Felstone Field, Dalson's Tears, the Writhing Haunt and Gahrron's Withering. Kill each lord and use his key on his cauldron.","|cffffd200Andorhal|r, the ruined city in the middle, has more undead quests.","Move on at level 57."},done="you're level 57 and all four cauldrons are done.",stuck="Fight the undead around Andorhal until you are.",tip="Undead can't be Sapped or Pick Pocketed. Use Gouge or Blind on a second enemy instead.",talents={"Level 55: |cffffd200Blood Splatter|r, once. Rupture and Garrote last longer.","Level 56–57: |cffffd200Improved Slice and Dice|r, 2 times. Slice and Dice lasts longer."},pins={{zone="Western Plaguelands",x=43,y=84,label="Chillwind Camp"},{zone="Western Plaguelands",x=37,y=57,label="Felstone Field"},{zone="Western Plaguelands",x=46,y=52,label="Dalson's Tears"},{zone="Western Plaguelands",x=53,y=66,label="Writhing Haunt"},{zone="Western Plaguelands",x=62,y=58,label="Gahrron's Withering"},{zone="Western Plaguelands",x=43,y=70,label="Andorhal"}},quests={"Western Plaguelands","Chillwind Camp","The Scourge Cauldrons","Andorhal"}},
  {kind="train",chapter=11,lv="56",lo=56,hi=56,place="Ironforge (fly from Chillwind Camp)",title="Level 56: new ranks",todo={"Fly to Ironforge (the Forlorn Cavern) or Stormwind (SI:7) and learn every new |cffe2c6ff|Hwfw:26|hrank|h|r.","Better food: |cffffd200Homemade Cherry Pie|r from a baker. Put it on |cff7fd4ffAlt|r + |cff7fd4ff2|r.","Fly back to Chillwind Camp and carry on."},done="you've learned every new |cffe2c6ff|Hwfw:26|hrank|h|r your |cffe2c6ff|Hwfw:34|htrainer|h|r offers.",bars={head="Action bar",rows={{id="food7",where="|cff7fd4ffAlt|r + |cff7fd4ff2|r |cff9a9a9abottom right bar|r",replaces="Deep Fried Plantains"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 56–57: |cffffd200Improved Slice and Dice|r, 2 times. Slice and Dice lasts longer."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}},quests={"Homemade Cherry Pie"}},
  {kind="quest",chapter=11,lv="56–58",lo=56,hi=58,place="Light's Hope, Eastern Plaguelands",title="Eastern Plaguelands",todo={"Ride east into |cffffd200Eastern Plaguelands|r and follow the road to |cffffd200Light's Hope Chapel|r on the far east side. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r.","The |cffffd200Argent Dawn|r at Light's Hope fight the undead. Their quests give good |cffe2c6ff|Hwfw:36|hXP|h|r and reputation.","In the ruined village of |cffffd200Darrowshire|r (south-west), talk to the little ghost girl |cffffd200Pamela Redpath|r. Her quests tell one of the saddest stories in WoW.","In a small house by the river in the far west, |cffffd200Tirion Fordring|r starts the famous |cffffd200Redemption|r chain. Move on at level 58."},done="you're level 58.",stuck="Fight the undead near Light's Hope Chapel until you are.",talents={"Level 56–57: |cffffd200Improved Slice and Dice|r, 2 times. Slice and Dice lasts longer.","Level 58–59: |cffffd200Lethality|r, 2 times. Your critical hits do more damage."},pins={{zone="Eastern Plaguelands",x=81.5,y=59,label="Light's Hope Chapel"},{zone="Eastern Plaguelands",x=36,y=90,label="Darrowshire"},{zone="Eastern Plaguelands",x=7,y=43,label="Tirion Fordring's house"},{zone="Eastern Plaguelands",x=27,y=11,label="Stratholme"}},quests={"Eastern Plaguelands","Light's Hope Chapel","Argent Dawn","Darrowshire","Pamela Redpath","Tirion Fordring","Redemption"}},
  {kind="train",chapter=11,lv="58",lo=58,hi=58,place="Ironforge or Stormwind",title="Level 58: new ranks",todo={"Fly from Light's Hope Chapel to Ironforge or Stormwind and learn every new |cffe2c6ff|Hwfw:26|hrank|h|r.","Then head for Winterspring (next step): take the boat to Auberdine and fly to Talonbranch Glade in Felwood."},done="you've learned every new |cffe2c6ff|Hwfw:26|hrank|h|r your |cffe2c6ff|Hwfw:34|htrainer|h|r offers.",bars={head="Action bar",notes={"Nothing new to place this time. New ranks stay on the same keys. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 58–59: |cffffd200Lethality|r, 2 times. Your critical hits do more damage."},pins={{zone="Stormwind",x=75.8,y=59.8,label="SI:7 (rogue trainers)"}}},
  {kind="quest",chapter=11,lv="58–60",lo=58,hi=60,place="Everlook, Winterspring",title="Winterspring",todo={"Fly to Talonbranch Glade in Felwood and walk north through the |cffffd200Timbermaw Hold|r tunnel. It comes out in |cffffd200Winterspring|r, a snowy valley.","At the hot springs, talk to |cffffd200Donova Snowden|r: her quests are about the Winterfall furbolgs.","Follow the road east to |cffffd200Everlook|r, a goblin town. Unlock the |cffe2c6ff|Hwfw:13|hflight path|h|r, make it your home and take every quest, like |cffffd200Are We There, Yeti?|r from Legacki.","For the last bars of |cffe2c6ff|Hwfw:36|hXP|h|r, run end-game dungeons with groups: Blackrock Depths, Lower Blackrock Spire, Dire Maul, Stratholme and Scholomance."},done="you're level 60!",stuck="Fight Winterfall furbolgs, or run Blackrock Depths with a group, until you are.",talents={"Level 58–59: |cffffd200Lethality|r, 2 times. Your critical hits do more damage.","Level 60: |cffffd200Cold Blood|r, once. A button: your next attack always crits. Use it before Eviscerate. That's all 51 points."},pins={{zone="Felwood",x=64.5,y=8,label="Timbermaw Hold (tunnel)"},{zone="Winterspring",x=61,y=38.5,label="Everlook"},{zone="Winterspring",x=31,y=45,label="Donova Snowden (hot springs)"},{zone="Winterspring",x=67,y=36,label="Winterfall Village (furbolgs)"}},quests={"Timbermaw Hold","Winterspring","Donova Snowden","Everlook","Are We There, Yeti?"}},
  {kind="train",chapter=11,lv="60",lo=60,hi=60,place="Nearest rogue trainer",title="Level 60: Instant Poison VI",todo={"Learn the last ranks and |cffffd200Instant |cffe2c6ff|Hwfw:21|hPoison|h|r VI|r.","Spend your last |cffe2c6ff|Hwfw:32|htalent|h|r point on |cffffd200Cold Blood|r. That's all 51. Cold Blood is a button: put it on the right bar and press it before a big Eviscerate, which then always crits."},done="Instant |cffe2c6ff|Hwfw:21|hPoison|h|r VI is on your main hand, Cold Blood is on your right bar, and all 51 |cffe2c6ff|Hwfw:32|htalent|h|r points are spent.",bars={head="Action bar",rows={{id="ipois6",where="Right bar, button |cffffd2001|r |cff9a9a9acounting from the top|r",replaces="Instant Poison V"},{id="coldblood",where="Right bar, button |cffffd20012|r |cff9a9a9acounting from the top|r"}},notes={"Food, bandages, poisons and sharpening stones are items: buy them, make them, or find them, and they show up in your bags. Drag them from your bag (|cff7fd4ffB|r) onto the key shown. When a better one replaces an old one, drop the new one on the same key and sell or use up the old ones.","New ranks of abilities you already have stay on the same key. If a button still shows the old rank, drag the new one from your spellbook (|cff7fd4ffP|r) onto it."}},talents={"Level 60: |cffffd200Cold Blood|r, once. A button: your next attack always crits. Use it before Eviscerate. That's all 51 points."},pins={{zone="Darnassus",x=37,y=22,label="Rogue trainers (Cenarion Enclave)"}},quests={"Instant Poison VI","Cold Blood"}},
  {kind="done",chapter=11,lv="60",lo=60,hi=60,place="Mount Hyjal",title="You made it to 60!",todo={"Visit |cffffd200Mount Hyjal|r, a new level 60 |cffe2c6ff|Hwfw:37|hzone|h|r reached through Winterspring.","From here on, it's about gear, dungeons and raids. Congratulations!"},talents={"Level 60: |cffffd200Cold Blood|r, once. A button: your next attack always crits. Use it before Eviscerate. That's all 51 points."},quests={"Mount Hyjal"}},
}
